quests[49407] = { id = 49407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maat meucheln", description = "Unter normalen Umständen würde ich Euch jetzt die Schriftrollen aushändigen und Euch losschicken.\n\nLeider leben wir aber nicht in normalen Zeiten.\n\nWie soll ein Mann denn bitte ein ehrbares Geschäft mit höchst illegalen Waren betreiben, wenn die Eisenfluträuber einem andauernd in die Quere kommen?\n\nIch biete Euch eine stolze Summe und die geforderte Schriftrolle für Euren Partner, wenn Ihr diese verfluchte Frau verschwinden lasst, die die Tribute einsammelt.\n\nIhr findet sie sicher an Harlans Tisch in der Taverne, wo sie sich mit MEINEM Gold betrinkt!", sourceObjective = "Tötet den Ersten Maat Trixie Schotriss.", completion = "Ihr habt es geschafft? Beeindruckend.", sourceObjectiveStatus = "unverified-source-field" }
quests[49408] = { id = 49408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piratenwürfel" }
quests[49409] = { id = 49409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist der Schatz?", description = "Wer von Euch stinkenden Hunden hat meinen Schatz ausgegraben?!\n\nEtwa Ihr, Malte? Ich weiß, dass Ihr in der Taverne des Toten letztes Grinsen wart, als ich über den Schatz sprach!\n\nOder Ihr, Nora Behrens, hm? Ihr habt mich schließlich schön abgefüllt damals!\n\nNubb Nubb, Euch habe ich auch auf dem Kieker! Ich traue keinem Ho-zen weiter, als ich ihn werfen kann. Das ist zwar SEHR WEIT, aber Ihr wisst, was ich meine!\n\n<Hier sind einige Zeilen unkenntlich gemacht.>\n\nJemand hat meinen verdammten Schatz gestohlen!\n\n<Unterzeichnet mit einem X.>", sourceObjective = "Befragt Malte, Nora Behrens und Nubb Nubb nach dem Schatz und findet ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[49411] = { id = 49411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kasernenbau" }
quests[49412] = { id = 49412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Henris Helfer", description = "Die Raubeine haben mir gesagt, ich soll die Felsen freimachen. DAVON war aber nicht die Rede!\n\nIhr seht stark aus. Bitte helft mir! Ich sterbe, wenn ich zu nahe an dieses Ding herankomme. Ich bin extrem allergisch gegen Bienen.", sourceObjective = "Tötet Roarr.", progress = "Das Vieh hasst Bienen wirklich...", completion = "Ich danke Euch vielmals! Auf zur nächsten Aufgabe!", sourceObjectiveStatus = "unverified-source-field" }
quests[49413] = { id = 49413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strolche mit Schriftrollen" }
quests[49417] = { id = 49417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiter der Raubeine", description = "Rulf meinte, dass Ihr noch für eine andere Aufgabe gebraucht werdet.\n\nEin reicher Stubenhocker bietet einen Haufen Gold für ein Alphamännchen aus dem Adlerhorst. Da kommt eigentlich nur ein Tier in Frage: Großfeder. Ich muss jetzt aber zurück ins Lager und ein besonders wildes Weibchen trainieren. Diese Aufgabe müsst Ihr allein erledigen.\n\nFindet Großfeder und schießt ihn mit einem Fesselschuss ab. Der Rest ist Euch überlassen.", sourceObjective = "Fangt Großfeder.", completion = "Unglaublich, dass Ihr das geschafft habt. Wusste ich doch, dass Ihr zu den Raubeinen passt!", sourceObjectiveStatus = "unverified-source-field" }
quests[49418] = { id = 49418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Boss", description = "Ihr habt bewiesen, dass Ihr hier einer der Platzhirsche seid. Boss Tak wird mit Euch reden wollen. Er ist im Norden und überprüft eines unserer Lager am Schmelzenden Gletscher. Macht Euch auf den Weg und helft ihm.\n\nOh, und ich rate Euch, ihm nicht direkt in die Augen zu schauen... oder auf seine Füße... oder auf sonst irgendetwas an ihm. Am besten Ihr schließt Eure Augen, wenn Ihr mit ihm redet.", sourceObjective = "Trefft Boss Tak im Lager der Raubeine am Schmelzenden Gletscher.", completion = "Ihr seid also der Neue? Egal. Ich habe ein Problem, bei dem Ihr mir helfen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[49419] = { id = 49419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefroren", description = "Hilpe, pippe! Ich kamm gerabe meime Bibben moch eppas befegem.\n\nHelpt mir hier rauspsukongen.", sourceObjective = "Findet die Quelle der Hitze an der Thermalquellenklippe.", progress = "Haft Ihr fass?", completion = "Panke fön!", sourceObjectiveStatus = "unverified-source-field" }
quests[49421] = { id = 49421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd auf Zul", description = "Zul zieht alle seine Truppen zurück zu seinem Stützpunkt am Tempel des Propheten.\n\nRastakhan hat berichtet, dass er auf dem Zocalo eine Armee aus allen aufstellen will, die ihm noch treu ergeben sind und eine Waffe tragen können. Offenbar hatte der alte König mehr Getreue, als Zul erwartet hätte.\n\nUnd darüber hinaus stehen ihm auch noch drei ihrer ältesten Loa zur Seite.\n\nMacht Euch auf und unterstützt ihre Armee mit Eurer Stärke.", sourceObjective = "Trefft Euch mit König Rastakhan beim Zocalo.", completion = "Bei der Jagd auf jemanden, der die Zukunft geseh'n hat, sollte man besser ein gewisses Maß an Vorsicht walt'n lass'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49422] = { id = 49422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ketzer", description = "Fallt über Zuls Fanatiker und Moguverbündete her. Macht Jagd auf sie und erlegt sie mit der Wildheit eines wahren Raubtiers. Für ihren Verrat sollen sie den gerechten Lohn erhalt'n.", sourceObjective = "Verheert den Tempel des Propheten.", completion = "Ohne die Geschosse der Ballisten am Himmel kann Pa'ku endlich tun, was sie so liebt: alle, die sie verärgern, aus sehr großer Höhe herabstürz'n lass'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49424] = { id = 49424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ganze Prophezeiung", description = "Zul, diese Schlange von 'nem Propheten. Ich hab ihm nie übern Weg getraut. Hatte immer das Gefühl, dass er uns nich' die ganze Prophezeiung erzählt hat.\n\nBetretet den Tempel von diesem \"Propheten\" un' seht nach, ob er Aufzeichnungen von sein' Vision' gemacht hat.\n\nWir müss'n wiss'n, was unsre Beute vorhat, bevor die richtige Jagd beginn' kann.", sourceObjective = "Findet und lest die 3 Worte des Zul.", progress = "So groß ist der Glaube an Zul nicht, dass ihm seine Anhänger blind vertrauen würden.", completion = "Zul ist so tief gesunken, dass er sogar Dazar selbst aufersteh'n lassen will? Kann man Zul überhaupt noch einen Zandalari nennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[49425] = { id = 49425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Goldene Stadt", description = "Rezan und Rastakhan haben nich' auf uns gewartet. Sie marschier'n den Berg hinauf in Richtung Atal'Dazar, der goldenen Stadt.\n\nIhr, Loti und ich müss'n sie schnell einhol'n und ihnen Luftunterstützung geb'n. Los geht's. Kommt an Bord!", sourceObjective = "Zerschlagt Zuls Streitkräfte auf der Straße nach Atal'Dazar.", completion = "Zul glaubt, mich aus MEINEM Reich aussperren zu können? Ich werde seine Seele verschlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49426] = { id = 49426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schachzug des Königs", sourceObjective = "Unterstützt Rezan und Rastakhan bei ihrer Belagerung von Atal'Dazar.", completion = "Er... Er ist tot...", sourceObjectiveStatus = "unverified-source-field" }
quests[49427] = { id = 49427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht unsere lila Elfen", description = "Wisst Ihr, {name}. Diese Elfen mögen lila sein, aber zur Allianz gehören sie trotzdem nicht.\n\nAuf jeden Fall sind sie viel aggressiver, als es für einen alten Dunkeleisenzwerg wie mich akzeptabel ist.\n\nAber wir schenken der Horde schön einen ein, wenn wir sie dezimieren. Könnt Ihr ein paar davon niedermetzeln?", sourceObjective = "Tötet 8 Einheiten der Horde an der östlichen Küste von Xibala.", completion = "Sie waren nicht gerade freundlich, stimmt's? Eine Sache weniger, um die ich mich sorgen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[49428] = { id = 49428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telemantischer Coup", description = "Gute Konkurrenz ist mir immer willkommen, {name}.\n\nAber es einfach vor unserer Nase rauszuteleportieren ist eine fiese Geschichte.\n\nZeigt dieser diebischen Elfe, was die Allianz mit Dieben macht. Wenn sie uns unfair kommen, schlagen wir noch unfairer zurück!", sourceObjective = "Tötet Dritte Telemantin Syranel und holt den Odem von Xibala zurück.", progress = "Habt Ihr den Odem von Xibala zurückgeholt?", completion = "Ein Zwerg hält sein Wort, {name}.\n\nHier ist Euer Anteil. Ich werde zusehen, dass dieser... Pott... der Allianz überbracht wird, garniert mit meinem Lob für Eure Taten.\n\nSieht nicht unbedingt überwältigend aus, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[49431] = { id = 49431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemütlich und warm", description = "Heya! Ist es hier nicht traumhaft? Ich könnte kaum entspannter sein. Nun ja, könnte ich schon, wenn diese Wolkenidioten mich in Ruhe lassen würden.\n\nHaut doch für mich ein paar Wolkengesichter um. Oh, und bringt mir ihre Essenzen. Damit halte ich die Wanne warm.", sourceObjective = "Sammelt 99 heiße Essenzen.", progress = "Ich brauche mehr Dampf! Los, die Wanne wird kalt!", completion = "Ooooh, ist das schön. Wunderschön. Springt doch einfach auch rein. Das Wasser ist wunderbar! Ach, und ignoriert das Blubbern.", sourceObjectiveStatus = "unverified-source-field" }
quests[49432] = { id = 49432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die trostlose Seele", description = "Wo is' meine Mutta? Habt Ihr sie vielleicht geseh'n?\n\nSie is' gleich wieder da, hat sie gesagt. Un' ich war ein gutes Mädchen un' hab gewartet un' gewartet un' gewartet. Ich weiß gar nich' mehr, wie lange.\n\nHier is' es so kalt un' einsam. Hey... Könnt Ihr mir helf'n, meine Mutta zu find'n? Ich werd Euch auch keinen Ärger mach'n.", sourceObjective = "Helft Keula, ihre Mutta in der Nekropole zu finden.", completion = "Es war töricht von Keulas Mutta zu glaub'n, dass sie es nich' auf die Andre Seite schafft. Aber jetzt sin' sie zusammen un' ich hab zwei weitere Seelen.\n\nHabt Ihr gut gemacht, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[49433] = { id = 49433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wendies", description = "Es ist wirklich ein Rätsel, wo all die Jungs hingeschafft wurden. Wer das war, ist allerdings kein Rätsel und Raubeine leben nach dem Motto: Auge um Auge und noch ein paar.\n\nLasst uns einige dieser Monster niedermetzeln.", sourceObjective = "Tötet 10 Wendigos.", completion = "Das wird meine Jungs unten am Hügel schützen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[49435] = { id = 49435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind alle hin?", description = "Meine Jungs sind verschwunden. Ihr werdet mir helfen, sie wiederzufinden.\n\nVerstanden?", sourceObjective = "Findet Hinweise auf die verschwundenen Raubeine.", completion = "Traurig. Zumindest weiß ich jetzt, dass der Rest ehrenvoll im Kampf gefallen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[49437] = { id = 49437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerfledderte Notiz", description = "<Die kurze, handschriftliche Notiz wurde mit Blut gekritzelt.>\n\nSie fingen mich, kurz nachdem ich verbannt wurde. Für Sklavenarbeit war ich zu schwach und zu abgemagert, um als Futter für die Tiere zu dienen.\n\nEigentlich wollten sie mich töten, aber einer mit Namen Shath'kar mischte sich ein. Er sagte, es wäre amüsant, mir zuzusehen, wie ich neben seinen anderen Gefangenen verhungere.\n\nIch habe kein gutes Leben geführt. Mir steht nichts zu. Aber an jeden Zandalarilandsmann, der das hier findet, habe ich eine Bitte...\n\nBohrt ein Schwert tief in den Wanst von Shath'kar und dreht es so oft, bis dieses Ungeheuer tot ist!", sourceObjective = "Tötet Shath'kar in der Schlängelnden Schlucht.", completion = "Ich habe die anderen Vulpera Shath'kars Namen voller Furcht flüstern hören. Danke, dass Ihr uns von ihm befreit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49439] = { id = 49439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache ist süß", description = "Rache ist normalerweise nicht meine Art, aber wer meine ganze Mannschaft tötet, darf nicht ungestraft davonkommen.\n\nKein Rückzug, keine Gnade!", sourceObjective = "Tötet Stampffuß.", completion = "Wenn man hier draußen überleben will, muss man hart rangehen. Heute haben wir den Tod meiner Leute blutig gerächt.\n\nDanke für Eure Hilfe. Wenn Ihr jemals Hilfe benötigt, werden die Raubeine Euch beistehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49440] = { id = 49440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach außen ein Bluttroll", description = "Einer unserer Späher, Jo'chunga, hat den Auftrag, die Bluttrolle zu infiltrier'n, aber wir ham länger nichts mehr von ihm gehört.\n\nIch möchte, dass Ihr Jo'chunga findet, damit wir erfahr'n, was er über die Bluttrolle herausgefund'n hat.\n\nWenn Ihr ihn find'n wollt, müsst Ihr Euch als eine der Bluttrollfrauen verkleidet da reinschleich'n. Sie genieß'n die größte Bewegungsfreiheit bei ihnen. Ich kenn' ein Ritual, mit dem ich Euch verwand'ln kann.\n\nHelft mir, das Ritual durchzuführ'n, damit ich Euch als Bluttroll tarnen kann.", sourceObjective = "Helft Hexendoktor Kejabu, das Ritual abzuschließen, um Euch als Bluttroll zu tarnen.", progress = "Hm? Was braucht Ihr?", completion = "Das Ritual is' abgeschloss'n. Ihr seid bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[49443] = { id = 49443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Hexenjagd", description = "Ich respektiere zwar die Arbeit, die man beim Schreiben dieses Folianten geleistet hat, aber das Ding liest sich wie eine technische Gebrauchsanleitung für Belagerungsmaschinen!\n\nIch werde eine Weile brauchen, um dieses Werk zu lesen und vielleicht etwas Nützliches darin zu finden. Und ich könnte etwas Hilfe dabei brauchen, wenn es Euch nichts ausmacht.\n\nZunächst wäre etwas mehr Licht hier drinnen sehr hilfreich...", sourceObjective = "Helft Luzilla Kronsteig bei ihren Studien des Folianten von Asche und Silber.", progress = "Seid Ihr fündig geworden?", completion = "Ah! Ausgezeichnet.\n\n<Luzilla holt eine große Nähnadel aus ihrem Nähzeug hervor.>\n\n...Ihr scheint verwirrt zu sein. Ich will es Euch erklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[49444] = { id = 49444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestampft" }
quests[49445] = { id = 49445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ursargerithandel", sourceObjective = "Wie Ihr zweifellos mitbekommen habt, ist Ursargerit ein kostbares Material, das in Verbindung mit Gegenständen große Macht entfaltet. Bei unserem Kampf gegen die Legion benötigen wir so viel Macht wie nur irgend möglich.\n\nBringt mir Euer gefundenes Ursargerit, dann kommen wir ins Geschäft.", sourceObjectiveStatus = "unverified-source-field" }
quests[49449] = { id = 49449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leder - Rang 1 freischalten", description = "Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine schwache Macht, die kurz von ihr ausgeht und dann verschwindet.\n\nAls sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49450] = { id = 49450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ereignisprotokoll", description = "Kein Wunder, dass unsere Arbeiter Angst davor haben, in diese Wälder zu gehen. Normalerweise halten sich die Bären und Spinnen von den Menschen fern... \n\nAber diese Tiere sind nicht normal!\n\nVater würde vor Wut toben, wenn die Produktion zum Erliegen käme. Bitte tötet diese Tiere, damit es auf der Farnwaldhöhe wieder sicher wird.", sourceObjective = "Tötet 10 bezauberte Wildtiere auf der Farnwaldhöhe.", completion = "Ich habe noch nie so... seelenlose Tiere gesehen. Als ob sie unter dem Einfluss eines Zaubers stehen würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49451] = { id = 49451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderurlaub", description = "Mein Vater sieht offensichtlich nicht, was direkt vor seiner Nase passiert. Er verbarrikadiert sich in seinem Büro und kommt erst spät nachts nach Hause...\n\nUnd nun bin ich, sein einziger Sohn, hier draußen mit seinen ganzen Arbeitern gefangen. Sie sitzen hier richtig in der Patsche, aber mein Vater wird ihnen niemals glauben.\n\nWenn er sich nicht um die Hintergründe dieses Angriffs kümmert, werde ich der Sache eben selbst auf den Grund gehen!", sourceObjective = "Befreit 5 umschlungene Holzfäller in Algersons Sägewerk.", completion = "Mein Sohn ist viel zu weichherzig. Er muss härter werden, wenn er dieses Geschäft eines Tages führen will!", sourceObjectiveStatus = "unverified-source-field" }
quests[49452] = { id = 49452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inventardefizit", description = "Meine Angestellten behaupten, sie wären angegriffen worden. Sie sagen, Wildtiere und Holzmänner würden unsere Arbeiter töten.\n\nIch sage, wir verlieren hier wertvolle Ausrüstung!\n\nHabt Ihr eine Vorstellung davon, wie viele betriebseigene Äxte mittlerweile da draußen herumliegen? So verschwenden sie mein hart erarbeitetes Geld!\n\nIch möchte, dass Ihr diese Werkzeuge zurückholt.", sourceObjective = "Sammelt 5 wiederbeschaffte Äxte von Algersons toten Holzfällern.", progress = "Ich gebe mein ganzes Geld aus, um den Arbeitern das Material zu beschaffen, das sie brauchen, und sie verlieren es dann ständig! Was soll ich denn noch alles durchgehen lassen?", completion = "Vielleicht sollte ich ihnen die Kosten für die Äxte zukünftig vom Lohn abziehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[49453] = { id = 49453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "VerDAMMt nochmal", description = "Diese Holzfäller zerstören den Wald und den Lebensraum der Tiere!\n\nDie Biber brauchen das Holz für ihre Dämme. Jetzt wuseln sie hier herum und sammeln die Holzreste auf.\n\nDas ist viel zu gefährlich für sie. Bitte helft mir und jagt sie zurück ins Wasser. Dort sind sie sicher.", sourceObjective = "Jagt 6 holznagende Biber zurück ins Wasser.", completion = "Juchhu! Jetzt sind die Biber wieder sicher vor den Spinnen und den Holzfällern!", sourceObjectiveStatus = "unverified-source-field" }
quests[49454] = { id = 49454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinneneiomelette", description = "Noch nie hat es in diesen Wäldern so viele Spinneneier gegeben.\n\nWenn die alle aus der letzten Zeit stammen... müssen sie zudem auch noch verderbt sein! Wir dürfen nicht zulassen, dass noch weitere dieser aggressiven Spinnen aus ihnen ausschlüpfen.\n\nZerstört auf Eurem Weg durch die Wälder diese Eier. Noch mehr Spinnen könnten zu einem unkontrollierbaren Befall führen!", sourceObjective = "Zerstört 12 Mooszahneier.", completion = "Danke vielmals.\n\nÖhm... Ihr habt da noch Spinneneischleim an Eurem Umhang.", sourceObjectiveStatus = "unverified-source-field" }
quests[49455] = { id = 49455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leder - Rang 2 freischalten", description = "Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine schwache Macht, die kurz von ihr ausgeht und dann verschwindet.\n\nAls sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.", sourceObjectiveStatus = "unverified-source-field" }
