quests[49464] = { id = 49464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sauroliskenschwänze", description = "In den oberen Schichten der Gesellschaft von Kul Tiras gibt es ein Gericht, das nur die besten Köche anbieten. Die Adeligen bezahlen Unsummen, um diese Delikatesse zu kosten. Eine Geschmacksextase für den gehobenen Gaumen.\n\nIch spreche vom Sauroliskenschwanz.\n\nDiese seltene Kostbarkeit muss nach allen Regeln der Kunst zubereitet werden. Soll ich sie kochen? Schmoren? Pochieren? Oder dämpfen und blanchieren? Das wird ein wahres Schmankerl!\n\nIch brauche aber mehrere Schwänze, um verschiedene Rezepte auszuprobieren.", sourceObjective = "Sammelt 5 Sauroliskenschwänze von Flechtenkiefersaurolisken.", sourceObjectiveStatus = "unverified-source-field" }
quests[49465] = { id = 49465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Optimale Ressourcenauslastung", description = "Ich erzähle Euch mal was über meine Angestellten.\n\nSie übertreiben immer maßlos! Ich gebe ihnen Arbeit mit fairem Gehalt und was ist der Dank? Ihnen fällt nichts Besseres ein, als eine Ausrede nach der anderen aufzutischen, warum sie angeblich nicht arbeiten können.\n\nDie Bäume sind zum Leben erwacht? Bäume? Laufen umher und attackieren Menschen? Also bitte. Da erzählt meine Oma ja bessere Märchen.\n\nWenn ich das glauben soll, brauche ich einen stichhaltigen Beweis.", sourceObjective = "Sammelt 5 holzverzierte Schädel in Algersons Sägewerk.", progress = "Ich biete ihnen gute Arbeit und gute Bezahlung. Und das ist nun ihr Dank?", completion = "<Algerson untersucht den Schädel.>\n\nAlso das ist ja... sehr interessant! Warum laufen meine Männer weg? Die sollten lieber diese Dinger einsammeln!\n\nDamit kann man ja ein Vermögen machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[49467] = { id = 49467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexe des Waldes", description = "Eine... Eine Hexe?!\n\nIch, äh... Ich würde Euch gerne helfen, wirklich, aber... ich muss mich bei meinem Vater melden.\n\nWieso haltet Ihr die Hexe nicht selbst auf? <Ein tapferer Abenteurer/Eine tapfere Abenteurerin> wie Ihr sollte mit einer Hexe doch keine Probleme haben.\n\nIch bin sicher, mein Vater würde Euch großzügig belohnen!", sourceObjective = "Tötet die Hexe des Waldes auf der Farnwaldhöhe.", progress = "Mein Sohn hat mir von der Hexe erzählt, {name}. Ich bin hierhergekommen, um mich um sie zu kümmern! Wenn man will, dass etwas richtig gemacht wird, dann muss man es selbst machen.", completion = "<Mainhardt mustert das Medaillon.>\n\nUndankbares Weib!", sourceObjectiveStatus = "unverified-source-field" }
quests[49468] = { id = 49468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut vernetzt", description = "Mich überrascht nicht, dass die Arbeiter trotz dieser Tiere in den Wäldern geblieben sind. Vater gibt es nicht gern zu, aber einige der Arbeiter zeichnen sich durch eine sehr hohe Arbeitsmoral aus.\n\nUnd nun haben die Spinnen sie gefangen!\n\nVielleicht wissen sie ja, was hier vor sich geht. Befreit sie aus den Spinnennetzen und findet heraus, was sie wissen!", sourceObjective = "Befreit 5 eingewebte Holzfäller.", completion = "Eine Hexe?! All das soll eine Hexe verursacht haben?!", sourceObjectiveStatus = "unverified-source-field" }
quests[49472] = { id = 49472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine titanische Leistung", description = "Illidan hat das Schicksal womöglich herausgefordert, doch Argus so nah an Azeroth heranzubringen, hat die Reaktion beschleunigt, die mit dem Kollaps des Nachtbrunnens begann.\n\nIch fürchte, was die Legion auf Argus tut, scheint weiter die Mächte zu destabilisieren, derer wir uns so viele Jahre unwissentlich bedient haben.\n\nNatürlich muss das näher untersucht werden.", sourceObjective = "Bringt 50 erweckende Essenz zu Arkanomant Vridiel.", progress = "Illidan mag der Überzeugung sein, dass für die Verbannung der Legion kein Preis zu hoch ist, aber das Schicksal könnte ihm noch das Gegenteil beweisen.", completion = "Die Veränderungen, die wir seit dem Aufbruch der Vindikaar nach Argus bei dieser Substanz feststellen, sind erschreckend.\n\nWas wird das alles am Ende für Azeroth bedeuten? Ich fürchte, das ist ein dunkles Omen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49473] = { id = 49473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine titanische Leistung", description = "Die Reaktion läuft von Tag zu Tag immer schneller ab. Vielleicht werden wir den Kampf gegen die Legion gewinnen, nur um etwas zu verlieren, das uns lieb und teuer ist.\n\nSind das die Vorzeichen eines größeren Umbruchs, der uns bevorsteht? Welches Schicksal erwartet unsere Welt, {name}?\n\nIch werde nach Antworten in meiner Schmiede suchen, wie ich es schon immer getan habe. Eure Antworten, vermute ich, erwarten Euch andernorts.", sourceObjective = "Bringt 50 erweckende Essenz zu Arkanomant Vridiel.", progress = "Wenn ich nicht bald herausfinde, was diese Störung verursacht, könnten wir schon zu tief darin verfangen sein, um umzukehren.", completion = "Nehmt das. Möge es Eure Bemühungen unterstützen, die Legion aufzuhalten... und unsere Welt zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[49474] = { id = 49474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verfluchte Splitter", description = "<Ein unnatürlich metallischer Splitter erregt mit seinem mehrfarbigen Schimmern Eure Aufmerksamkeit. Als Ihr ihn berührt, bläht sich ein Ende auf und schmilzt dann dahin. Tropfen fallen zischend zu Boden und ein ätzender Gestank erfüllt Eure Nase.\n\nIn Dalaran sollte es jemanden geben, der sich mit Metallen beschäftigt und mehr darüber sagen kann.>", sourceObjective = "Bringt den verfluchten Splitter zu Arkanomant Vridiel in Dalaran auf den Verheerten Inseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[49477] = { id = 49477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschende Unterstützung", description = "<Ihr habt auf dem Boden ein zerrissenes Sendschreiben der Horde gefunden...\n\nAnscheinend ist eine Gruppe der Verlassenen unter der Führung eines Mannes namens Chadwick Paxton hierher entsandt worden, um Nazmir zu erkunden.\n\nIhr könnt Euch den Sinn dieser Mission nicht erklären, aber anhand der enthaltenen Koordinaten könnt Ihr den Weg der Gruppe nachvollziehen.\n\nVielleicht trefft Ihr die Späher bei den Koordinaten an und könnt sie überzeugen, Euch im Kampf gegen die Bluttrolle zu unterstützen.>", sourceObjective = "Findet Chadwick Paxton, den Anführer des Spähtrupps der Verlassenen.", completion = "Oh, hallo, schön Euch hier draußen im Sumpf zu treffen. Ja, ich bin Chadwick Paxton. Oder zumindest ungefähr die Hälfte von ihm. Könntet Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[49479] = { id = 49479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über das Ziel hinaus", description = "Die Sethrak scheinen zu glauben, dass es in Nazmir etwas gibt, mit dem sich die zerstörerische Kraft dieses Edelsteins entfesseln lässt.\n\nSo etwas haben wir zwar nicht, aber dafür eine gute Alternative. Eine wahnsinnige Hexenmeisterin, die bereit ist, mit Magie zu experimentieren.\n\nSprecht mit Ingrid und lasst sie den Prozess zum Entfesseln der wahren Macht dieses Edelsteins in Gang setzen.", sourceObjective = "Lasst Ingrid den Himmelsruferedelstein ermächtigen.", progress = "Nehmt Euch in Gegenwart von Ingrid etwas in Acht. Sie übertreibt es manchmal ein wenig.", completion = "Dieser Edelstein scheint bereit zu sein, etwas Schaden anzurichten. Richten wir ihn... erst einmal in eine andere Richtung.", sourceObjectiveStatus = "unverified-source-field" }
quests[49488] = { id = 49488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal'gurub", description = "Mein Prophet is' ein treuer Diener, aber er hat seine eignen Vorstellungen von der Ordnung der Dinge.\n\nIch sende ihn nach Tal'gurub, um dort ein durch ihn verursachtes Schlamassel wieder in Ordnung zu bring'n. Einer seiner Schüler, ein Hexendoktor namens Vol'jamba, hat die Enklave der Gurubashi eingenomm' und meine Wachen vertrieb'n.\n\nTrefft Euch in Tal'gurub mit Zul und kümmert Euch um dieses Problem. Stellt sicher, dass ihn nichts... ablenkt.", sourceObjective = "Trefft Euch mit Zul dem Propheten in Tal'gurub.", completion = "Ach, ja, meine neue Eskorte!\n\nIhr seid hier, um den Will'n des Königs durchzusetz'n. Es wär doch schade, wenn der alte Rastakhan von Euch enttäuscht werd'n würde. Vor allem nach Eurer Leistung in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[49489] = { id = 49489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig mehr Körper", description = "Eigentlich bin ich hier, um mich um mein' eig'nsinnigen Schüler zu kümmern. Ihr könnt Euch mit seinen Anhängern herumschlag'n.\n\nIch hatte 'ne Zukunftsvision und sie war sehr besorgniserregend. Rote, vergiftete Flüsse un' Leichen in den Straß'n. Und diese \"Jambani\" erklärten sich zu den neu'n Herrschern von Zuldazar. Das darf nicht passier'n!\n\nZu Euerm Glück weiß ich das zu verhinder'n. Ihr werdet bemerk'n, dass noch 'ne wichtige Zutat in ihren Kesseln fehlt.\n\n<Er starrt Euch an.>\n\nVielleicht etwas, das dem Ganz'n 'n wenig Körper verleiht?", sourceObjective = "\"Verbessert\" 2 Gebräue, die von den Atal'jamba-Akolythen zubereitet wurden.", completion = "Feuer mit Feuer bekämpf'n, sagt man. Oder in diesem Fall, Gift mit Idioten, die ihren Meistern in die Quere kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49490] = { id = 49490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Urne der Stimmen", description = "Vol'jamba besitzt die wahre Sicht. Er wird sich also in diesem Moment schon auf uns vorbereit'n.\n\nSeine wahre Sicht is' aber fehlerhaft. Wir werden seinem Dasein ein Ende bereit'n und seine Anhänger gleich mit ihm untergeh'n lassen. Euer Werkzeug dazu ist die Urne der Stimmen.\n\nNehmt sie Euch und erkundet Tal'gurub. Zerstört seine Golems und Masken. Sobald ihre Geister befreit sin', werd'n sie die Urne füll'n.\n\nVersucht, nicht zu sterb'n, während Ihr sie haltet. Die Urne der Stimmen ist nicht wählerisch.", sourceObjective = "Sammelt 30 Seelenunzen von Gegnern in Tal'gurub.", completion = "Es läuft alles nach Plan. Sorgt Euch nicht um die. Das war schon immer ihr Schicksal.", sourceObjectiveStatus = "unverified-source-field" }
quests[49491] = { id = 49491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nahrung für das Voodoo", description = "Es bleibt keine Zeit! Sie entzieh'n uns unsere Seel'n... Benutz'n uns... Dunkles Voodoo...\n\n<Loapriesterin Izitas Geist entschwindet und ihre Stimme klingt sanft und fern.>\n\nDie Totems... verbrennt sie...\n\nDann werd'n wir frei sein...!", sourceObjective = "Sammelt 8 Voodoototems.", progress = "<Die Kohlenpfanne brennt lichterloh.>", completion = "<Als das Feuer an den Totems zehrt, erheben sich die Geister der Gurubashi aus der Asche.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49492] = { id = 49492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'jambas Arroganz", description = "Vol'jamba glaubt, seine Sicht wär meiner überleg'n. Vor vielen Jahr'n hab ich ihn vor solcher Arroganz gewarnt, aber jetzt seh'n wir ja, wie gut er zugehört hat.\n\n<Zul schmunzelt.>\n\nEr will uns sicherlich aufhalt'n auf unsrem Weg zu sei'm Versteck. Hört Euch sein Gerede an, aber denkt dran, dass er verzweifelt versucht, sich zu rett'n. Seine Sicht ist durch Angst getrübt.\n\nZerstört seine Masken, dann könn' wir die Passage ungehindert durchquer'n.", sourceObjective = "Zerstört Vol'jambas Masken.", progress = "Seine Arroganz blendet ihn. Bald wird er den Fehler in seinem Handeln versteh'n.", completion = "Wie gesagt: Seine Sicht ist durch Angst getrübt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49493] = { id = 49493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuls ethisches Dilemma", description = "Hm.\n\nDie Gurubashi ham den Ruf, verräterisch und schwach zu sein. Ihre Aktivitäten in Zul'Gurub werd'n noch für Generationen ein Schandfleck in unsern Aufzeichnungen sein.\n\nAndererseits...\n\nDie Zandalari find'n es unter ihrer Würde, Sklaven einzusetzen. Wir sind stark un' kompetent. Allein die Existenz von Gedankensklaven in dieser großartigen Stadt is' 'ne Beleidigung.\n\nEs gibt einen Gesang, der ihre Gedanken befreit. Stimmt ihn in der Nähe der Gedankensklaven an, um sie zu befrei'n.\n\nOder Ihr tötet sie einfach. Für mich is' da kein Unterschied.", sourceObjective = "Befreit 9 Gedankensklaven.", completion = "Schwäche oder Stolz... Ich denk' häufig über die Prioritäten der Zandalari nach.", sourceObjectiveStatus = "unverified-source-field" }
quests[49494] = { id = 49494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuvembibräu", description = "Zuvembibräu is' das wohl heimtückischste Gebräu eines Hexendoktors.\n\nEs wird durch die Geistesstärke des Kesselmeisters befeuert und übernimmt den Willen von denen, die seine Dämpfe einatmen. Es macht sie folgsam und leicht manipulierbar.\n\nEs is' niedere Magie, die auf uralten Tricksereien und Rezepten beruht und die nur Hexendoktoren mit 'nem gewissen Talent bekannt ist. Wenn wir dieses Gebräu auslöschen wollen, müssen wir die töten, die es brauen.\n\nFindet den Zuvembibrauer, der sich hier versteckt, und stellt sicher, dass dieses Wissen ausgelöscht wird.", sourceObjective = "Tötet Zuvembibrauer Zekal.", progress = "Diese primitive Magie darf sich nich' weiter ausbreiten.", completion = "Gut. Die Gefahr wurde gebannt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49495] = { id = 49495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal erzwingen", description = "Vol'jamba is' damit beschäftigt, seine Macht zu festig'n. Er hat vorausgesehen, dass er kämpf'n und vielleicht sterb'n wird. Also nutzt er alle Möglichkeiten, die er hat, um sich zu rett'n.\n\nIhr müsst jetz' meine Hände sein. Sobald ich mich zeige, wird er komm'. Ihr müsst alle Vorbereitungen, die er für diesen Tag getroff'n hat, sabotier'n.\n\nFührt meine Anweisungen aus und der König wird uns mit Freuden empfangen, wenn das hier vorbei is'.", sourceObjective = "Sabotiert Vol'jambas Vorsichtsmaßnahmen.", progress = "Seine Vision is' fehlerhaft. Wir werden das nutzen, um ihn auszuschalten.", completion = "<Zul reibt sich die Hände.>\n\nGut. Jetzt könn'n wir ihn rauslock'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49522] = { id = 49522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karl-Jans Bezahlung", description = "Gut gemacht. Wirklich sehr gut gemacht.\n\nSeht Ihr die verstaubte Kiste in der Ecke da? Darin findet Ihr die alte Schriftrolle und eine großzügige Goldbelohnung, wie abgemacht.\n\nBitte nehmt die Sachen an Euch. Ihr habt sie wirklich verdient.", sourceObjective = "Öffnet die verstaubte Kiste.", sourceObjectiveStatus = "unverified-source-field" }
quests[49523] = { id = 49523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Minusgeschäft", description = "<Karl-Jan ist geflohen!\n\nRoko, der Tortollanerhändler, der diesen Handel arrangiert hat, will bestimmt wissen, was vorgefallen ist.\n\nAls Ihr das letzte Mal mit ihm gesprochen habt, sagte Roko, er würde nach Boralus aufbrechen.>", sourceObjective = "Sprecht mit Roko auf dem Handelswindmarkt.", completion = "Hm. Es war also Betrug? Tut mir leid, dass ich Euch in Gefahr gebracht habe.\n\nDieser Mann sollte vor Gericht gestellt werden. Er mag sich jetzt verborgen halten, aber ich bin sehr, sehr geduldig.", sourceObjectiveStatus = "unverified-source-field" }
quests[49529] = { id = 49529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühjahrsputz" }
quests[49531] = { id = 49531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effektive Werbung", description = "Wir Zischkolbens sind zwar keine Goblins, aber wir erkennen ein gutes Geschäft, wenn es sich bietet! Die Resortangestellten werden ausgebildet und wir bringen alles wieder auf Vordermann. Uns fehlt nur noch die richtige Werbung!\n\n<Wulferd hält ein Kästchen in die Höhe, das Euch bekannt vorkommt.>\n\nBestaunt die wundersame gnomische Entwicklung namens S.E.L.F.I.E.-Kamera! Wenn wir nur jemanden hätten, der für uns die wundervolle Atmosphäre dieses Ortes einfangen würde.\n\nUnd denkt daran: Schaut so, also hättet Ihr den besten Tag Eures Lebens!", sourceObjective = "Macht S.E.L.F.I.E.s mit den Sehenswürdigkeiten und der Tierwelt des Resorts.", progress = "Wenn Ihr nicht mindestens über das halbe Bild grinst, will ich es nicht sehen.", completion = "Die sind perfekt geworden. Ihr seht fantastisch aus! Jetzt muss ich nur noch abklären, wie wir die Fotos an unsere Kunden bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49532] = { id = 49532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Schattenmondtal!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Blutwache Gulmok im Schattenmondtal in der Scherbenwelt zu melden.\n\nDie Brennende Legion beabsichtigt, Schattenmond zu belagern, aber unsere Elitestreitkräfte der Kor'kron werden ihnen zeigen, was es bedeutet, sich mit der Horde anzulegen.\n\nZerschmettert die Legion.\n\nFür die Horde!", sourceObjective = "Sprecht mit Blutwache Gulmok im Schattenmondtal in der Scherbenwelt.", completion = "Willkommen auf dem Schlachtfeld!", sourceObjectiveStatus = "unverified-source-field" }
quests[49533] = { id = 49533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Der Heulende Fjord!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Apotheker Lysander im Heulenden Fjord zu melden.\n\nDie Verlassenen haben eine Stellung an der Ostküste von Nordend errichtet.\n\nEs ist an der Zeit, die Geißel jetzt mit unserer militärischen Macht und einer neuen Seuche anzugreifen, die von der Königlichen Apothekervereinigung entwickelt wurde.\n\nFür die Horde!", sourceObjective = "Sprecht mit Apotheker Lysander im Heulenden Fjord.", completion = "Ah, da seid Ihr ja, {name}!\n\nMachen wir uns an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[49534] = { id = 49534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Zul'Drak!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kreuzfahrerlord Lantinga in Zul'Drak zu melden.\n\nDie Geißel massakriert Bevölkerung in Zul'Drak und verwandelt sie, um sie Teil ihrer Armee werden zu lassen.\n\nHelft dem Argentumkreuzzug und der Schwarzen Klinge, diese Bedrohung auszuschalten.\n\nFür die Horde!", sourceObjective = "Sprecht mit Kreuzfahrerlord Lantinga in Zul'Drak.", completion = "Tod und Sakrilege pervertieren dieses Land.\n\n<Lantinga stößt einen langen Seufzer aus.>\n\nAber zum Glück sind wir jetzt hier, um das zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49535] = { id = 49535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Sholazarbecken!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Erzmagier Pentarus in Dalaran über dem Kristallsangwald zu melden.\n\nHemet Nesingwary ist mit seiner Expeditionseinheit zum Sholazarbecken entsandt worden und gilt jetzt als verschollen.\n\nWir wissen nicht allzu viel über die üppige Landschaft von Sholazar, aber das Becken birgt vielleicht einige Geheimnisse, die für unseren Kampf gegen den Lichkönig von Vorteil sein könnten.\n\nFür die Horde!", sourceObjective = "Sprecht mit Erzmagier Pentarus in Dalaran über dem Kristallsangwald.", completion = "Ich bin froh, dass Ihr hier seid, {race}. Wir haben schon eine ganze Weile nichts mehr von Hemet gehört und ich könnte wirklich Eure Hilfe bei der Suche nach ihm brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49536] = { id = 49536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Sturmgipfel!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Rin Duoctane in Dalaran über dem Kristallsangwald zu melden.\n\nDie Goblins von K3 haben in den Sturmgipfeln eine Stadt errichtet und einen Botschafter entsandt, um Abenteurer zu rekrutieren.\n\nSprecht mit Rin, um herauszufinden, was die K3-Goblins benötigen. Sie wären wertvolle Verbündete in unserem Kampf gegen den Lichkönig.\n\nFür die Horde!", sourceObjective = "Sprecht mit Rin Duoctane in Dalaran über dem Kristallsangwald.", completion = "Also, ich hab da mal einen explosiven Vorschlag für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[49537] = { id = 49537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Eiskrone!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Himmelshäscher Klum in Dalaran über dem Kristallsangwald zu melden.\n\nDie Kriegshymnenoffensive braucht mehr Abenteurer, um ihren Angriff auf die Eiskronenzitadelle und Arthas selbst zu verstärken.\n\nDie Zeit ist gekommen, den Lichkönig für seine Verbrechen zahlen zu lassen.\n\nFür die Horde!", sourceObjective = "Sprecht mit Himmelshäscher Klum in Dalaran über dem Kristallsangwald.", completion = "Die Kriegshymnenoffensive ist bereit, die Geißel direkt anzugreifen, {class}. Seid auch Ihr bereit für diese Herausforderung?", sourceObjectiveStatus = "unverified-source-field" }
quests[49538] = { id = 49538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Jadewald!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei General Nazgrim in Orgrimmar zu melden.\n\nDie jüngsten Siege in unseren Seeschlachten gegen die Allianz stärken unsere Entschlossenheit.\n\nMeldet Euch in der Feste Grommash und unterstützt die Invasionsflotte der Horde.\n\nFür die Horde!", sourceObjective = "Meldet Euch bei General Nazgrim in der Feste Grommash.", completion = "Lok'tar ogar, {name}. Ihr kommt keinen Moment zu früh...", sourceObjectiveStatus = "unverified-source-field" }
quests[49539] = { id = 49539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Tal der Vier Winde!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Chen Sturmbräu im Tal der Vier Winde zu melden.\n\nVon dem Abenteuergeist der Sturmbräus kann die Horde viel lernen.\n\nReist mit den Sturmbräus und lernt die Geheimnisse von Pandaria kennen.\n\nFür die Horde!", sourceObjective = "Sprecht mit Chen Sturmbräu im Tal der Vier Winde.", completion = "Ihr seht wie jemand aus, dessen Leben etwas Aufregung braucht. Aufregung... und Bier!", sourceObjectiveStatus = "unverified-source-field" }
quests[49540] = { id = 49540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Krasarangwildnis!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Zhus Wacht in der Krasarangwildnis zu melden.\n\nEs gibt Gerüchte, dass die Pandaren in der Krasarangwildnis sich ungewöhnlich benehmen.\n\nSprecht mit Ken-Ken in Zhus Wacht. Vielleicht weiß er, was das lethargische Verhalten der Pandaren ausgelöst hat.", sourceObjective = "Sprecht mit Ken-Ken in der Krasarangwildnis.", completion = "Was zum Knatzel ist hier los, {race}?!\n\nWarum sind diese Pandaren so traurig?", sourceObjectiveStatus = "unverified-source-field" }
quests[49541] = { id = 49541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Kun-Lai-Gipfel!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Lehrensucher Cho am Kun-Lai-Gipfel zu melden.\n\nSprecht mit dem Botengrummel im Tal der Vier Winde. Er wird Euch den Weg zum Kun-Lai-Gipfel zeigen.\n\nFür die Horde!", sourceObjective = "Sprecht mit dem Botengrummel im Tal der Vier Winde.", completion = "Ihr wollt zum Kun-Lai-Gipfel? Hier entlang! Immer hier entlang!", sourceObjectiveStatus = "unverified-source-field" }
quests[49542] = { id = 49542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Tonlongsteppe!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Taran Zhu in der Tonlongsteppe zu melden.\n\nDie Shado-Pan wollen ihr Land aus den Klauen der Yaungol zurückerobern, aber sie haben dafür nicht genügend Kämpfer.\n\nUnterstützt sie bei ihrem Angriff auf die Yaungol.\n\nFür die Horde!", sourceObjective = "Sprecht mit Taran Zhu in der Tonlongsteppe.", completion = "Willkommen in der Tonlongsteppe, Fremdling.\n\nWenn Ihr schon darauf besteht, Euch in die dunkelsten Winkel Pandarias zu wagen, dann könnt Ihr Euch dabei auch gleich nützlich machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49543] = { id = 49543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Schreckensöde!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Bogenmeisterin Li auf dem Schlangenrücken im Tal der Ewigen Blüten zu melden\n\nDie Shado-Pan wollen die Mantisarmee davon abhalten, ganz Pandaria zu überrennen.\n\nSichert Euch einen Drachen und fliegt zum Schlangenrücken, um mit Bogenmeisterin Li zu sprechen.\n\nDas Schicksal ruft!", sourceObjective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49545] = { id = 49545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Frostfeuergrat!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Scharfseher Drek'Thar im Frostfeuergrat zu melden.\n\nDie Zerstörung des Dunklen Portals hat die Invasion der Eisernen Horde nach Azeroth aufgehalten, aber jetzt müssen wir den Kampf zu ihnen tragen.\n\nMithilfe von Scharfseher Drek'Thar können wir auf Draenor eine strategische Stellung errichten, um unsere Feinde zu bekämpfen.\n\nFür die Horde!", sourceObjective = "Sprecht mit Scharfseher Drek'Thar im Frostfeuergrat.", completion = "Ich freue mich, Euch nach dem Tanaandschungel wohlbehalten zu sehen.\n\nWir haben viel Arbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[49546] = { id = 49546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Gorgrond!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Durotan in Gorgrond zu melden.\n\nDurotan ist auf der Suche nach Verbündeten, um die wilde Landschaft von Gorgrond abzusuchen und vielleicht uralte Mächte zu finden, die uns helfen könnten, die Eiserne Horde zu vernichten.\n\nSprecht mit ihm und findet heraus, welche Geheimnisse das Land birgt.\n\nFür die Horde!", sourceObjective = "Sprecht mit Durotan in Gorgrond.", completion = "Gorgrond ist kein Ort für eine Armee. Wir betreten nun die Stätte der Legenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49547] = { id = 49547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Talador!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Vorarbeiter Grobash in Talador zu melden.\n\nDie Eiserne Horde will Talador übernehmen. Die Gegend ist perfekt geeignet, um schnell und widerstandslos Verstärkung in jeden anderen Teil von Draenor zu entsenden.\n\nVorarbeiter Grobash errichtet zurzeit einen Außenposten in Talador. Reist dorthin und haltet die Eiserne Horde auf.\n\nFür die Horde!", sourceObjective = "Sprecht mit Vorarbeiter Grobash in Talador.", completion = "Es ist schön, Euch zu sehen, Kommandant {name}. Ich könnte Euren Rat brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49548] = { id = 49548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Spitzen von Arak!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Azik in den Spitzen von Arak zu melden.\n\nEs wurde gemeldet, dass flügellose Arakkoa aus den Spitzen von Arak fliehen. Gerüchten zufolge fliehen sie vor einer Superwaffe der Eisernen Horde.\n\nWir müssen herausfinden, warum sie ihre Heimat verlassen und was mit ihren Flügeln geschehen ist.\n\nFür die Horde!", sourceObjective = "Sprecht mit Azik in den Spitzen von Arak.", completion = "<Azik mustert Euch von oben bis unten.>\n\nAzik könnte wetten, dass Ihr bei Eurem Volk jemand Wichtiges seid.\n\nKommt doch näher. Azik könnte Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49549] = { id = 49549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Nagrand!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Steingardist Brox in Nagrand auf Draenor zu melden.\n\nThrall errichtet einen Außenposten der Horde und benötigt Unterstützung, um den Kriegshymnenklan aufzuhalten.\n\nSprecht mit Bron Himmelshorn, um nach Nagrand zu fliegen, und wendet Euch dann an die Versorgungskarawane.\n\nFür die Horde!", sourceObjective = "Sprecht mit Steingardist Brox in Nagrand auf Draenor.", completion = "Sie kamen... aus dem... Nichts.\n\n<Der Steingardist wird fast ohnmächtig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49550] = { id = 49550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Schattenmondtal!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Schwadronskommandant Nuainn im Schattenmondtal in der Scherbenwelt zu melden.\n\nDie Brennende Legion belagert die Wildhammerfeste und bedroht das Leben unserer Leute dort.\n\nWir müssen die Feste verstärken und den unerbittlichen Angriff der Brennenden Legion aufhalten!\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Schwadronskommandant Nuainn im Schattenmondtal in der Scherbenwelt.", completion = "Die überrennen uns hier fast.\n\nIch hoffe, Ihr seid hier, um zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49551] = { id = 49551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Der Heulende Fjord!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Macalroy im Heulenden Fjord zu melden.\n\nDie Hafenstadt Valgarde befindet sich inmitten des Heulenden Fjords und bietet der Allianz eine vorteilhafte Position für einen Angriff auf die Geißel.\n\nUnterstützt die dort stationierten Soldaten.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Macalroy im Heulenden Fjord.", completion = "Was ist denn?\n\nSeht Ihr nicht, dass ich beschäftigt bin, diesen Hafen hier vorzubereiten, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[49552] = { id = 49552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Zul'Drak!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Kreuzfahrerlord Lantinga in Zul'Drak zu melden.\n\nDie Geißel massakriert die Bevölkerung in Zul'Drak und verwandelt sie, um sie Teil ihrer Armee werden zu lassen.\n\nHelft dem Argentumkreuzzug und der Schwarzen Klinge, diese Bedrohung auszuschalten.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Kreuzfahrerlord Lantinga in Zul'Drak.", completion = "Tod und Sakrilege pervertieren dieses Land.\n\n<Lantinga stößt einen langen Seufzer aus.>\n\nAber zum Glück sind wir jetzt hier, um das zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49553] = { id = 49553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Sholazarbecken!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Erzmagier Pentarus in Dalaran über dem Kristallsangwald zu melden.\n\nHemet Nesingwary ist mit seiner Expeditionseinheit zum Sholazarbecken entsandt worden und gilt jetzt als verschollen.\n\nWir wissen nicht allzu viel über die üppige Landschaft von Sholazar, aber das Becken birgt vielleicht einige Geheimnisse, die für unseren Kampf gegen den Lichkönig von Vorteil sein könnten.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Erzmagier Pentarus in Dalaran über dem Kristallsangwald.", completion = "Ich bin froh, dass Ihr hier seid, {race}. Wir haben schon eine ganze Weile nichts mehr von Hemet gehört und ich könnte wirklich Eure Hilfe bei der Suche nach ihm brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49554] = { id = 49554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Sturmgipfel!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Rin Duoctane in Dalaran über dem Kristallsangwald zu melden.\n\nDie Goblins von K3 haben in den Sturmgipfeln eine Stadt errichtet und einen Botschafter entsandt, um Abenteurer zu rekrutieren.\n\nSprecht mit Rin, um herauszufinden, was die K3-Goblins benötigen. Sie wären wertvolle Verbündete in unserem Kampf gegen den Lichkönig.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Rin Duoctane in Dalaran über dem Kristallsangwald.", completion = "Also, ich hab da mal einen explosiven Vorschlag für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[49555] = { id = 49555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Eiskrone!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Offizier Van Rossem in Dalaran über dem Kristallsangwald zu melden.\n\nDie Expedition Valianz braucht mehr Abenteurer, um ihren Angriff auf die Eiskronenzitadelle und Arthas selbst zu verstärken.\n\nDie Zeit ist gekommen, den Lichkönig für seine Verbrechen zahlen zu lassen.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Offizier Van Rossem in Dalaran über dem Kristallsangwald.", completion = "Die Expedition Valianz ist bereit, die Geißel direkt anzugreifen, {class}. Seid auch Ihr bereit für diese Herausforderung?", sourceObjectiveStatus = "unverified-source-field" }
quests[49556] = { id = 49556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Jadewald!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend in der Burg Sturmwind in Sturmwind zu melden.\n\nGroßadmiralin Jes-Tereth stellt ein Team für eine Mission höchster Priorität zusammen.\n\nBegebt Euch sofort zur Burg Sturmwind, um Euch unterweisen zu lassen.\n\nRuhm der Allianz!", sourceObjective = "Meldet Euch bei Großadmiralin Jes-Tereth in der Burg Sturmwind.", completion = "Unsere Rolle ist äußerst wichtig, {name}.\n\nAdmiral Taylor und sein Flaggschiff sind verschwunden. Was noch wichtiger ist: Der junge Prinz war bei ihm und unser primäres Ziel besteht darin, ihn sicher zurück nach Hause zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49557] = { id = 49557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Tal der Vier Winde!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Chen Sturmbräu im Tal der Vier Winde zu melden.\n\nVon dem Abenteuergeist der Sturmbräus kann die Allianz viel lernen.\n\nReist mit den Sturmbräus und lernt die Geheimnisse von Pandaria kennen.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Chen Sturmbräu im Tal der Vier Winde.", completion = "Ihr seht wie jemand aus, dessen Leben etwas Aufregung braucht. Aufregung... und Bier!", sourceObjectiveStatus = "unverified-source-field" }
quests[49558] = { id = 49558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Krasarangwildnis!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Zhus Wacht in der Krasarangwildnis zu melden.\n\nEs gibt Gerüchte, dass die Pandaren in der Krasarangwildnis sich ungewöhnlich benehmen.\n\nSprecht mit Ken-Ken in Zhus Wacht. Vielleicht weiß er, was das lethargische Verhalten der Pandaren ausgelöst hat.", sourceObjective = "Sprecht mit Ken-Ken in der Krasarangwildnis.", completion = "Was zum Knatzel ist hier los, {race}?!\n\nWarum sind diese Pandaren so traurig?", sourceObjectiveStatus = "unverified-source-field" }
quests[49559] = { id = 49559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Kun-Lai-Gipfel!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Lehrensucher Cho am Kun-Lai-Gipfel zu melden.\n\nSprecht mit dem Botengrummel im Tal der Vier Winde. Er wird Euch den Weg zum Kun-Lai-Gipfel zeigen.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit dem Botengrummel im Tal der Vier Winde.", completion = "Ihr wollt zum Kun-Lai-Gipfel? Hier entlang! Immer hier entlang!", sourceObjectiveStatus = "unverified-source-field" }
quests[49560] = { id = 49560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Tonlongsteppe!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Taran Zhu in der Tonlongsteppe zu melden.\n\nDie Shado-Pan wollen ihr Land aus den Klauen der Yaungol zurückerobern, aber sie haben dafür nicht genügend Kämpfer.\n\nUnterstützt sie bei ihrem Angriff auf die Yaungol.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Taran Zhu in der Tonlongsteppe.", completion = "Willkommen in der Tonlongsteppe, Fremdling.\n\nWenn Ihr schon darauf besteht, Euch in die dunkelsten Winkel Pandarias zu wagen, dann könnt Ihr Euch dabei auch gleich nützlich machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49561] = { id = 49561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Schreckensöde!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Bogenmeisterin Li auf dem Schlangenrücken im Tal der Ewigen Blüten zu melden.\n\nDie Shado-Pan wollen die Mantisarmee davon abhalten, ganz Pandaria zu überrennen.\n\nSichert Euch einen Drachen und fliegt zum Schlangenrücken, um mit Bogenmeisterin Li zu sprechen.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49562] = { id = 49562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Schattenmondtal!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Prophet Velen im Schattenmondtal auf Draenor zu melden.\n\nDie Zerstörung des Dunklen Portals hat die Invasion der Eisernen Horde nach Azeroth aufgehalten, aber jetzt müssen wir den Kampf zu ihnen tragen.\n\nMit Prophet Velens Hilfe können wir auf Draenor eine strategische Stellung errichten, um unsere Feinde zu bekämpfen.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Prophet Velen im Schattenmondtal auf Draenor.", completion = "<Prophet Velen heißt Euch mit einem neugierigen Blick und einem herzlichen Nicken willkommen.>\n\nUnd so nimmt alles seinen Anfang...", sourceObjectiveStatus = "unverified-source-field" }
quests[49564] = { id = 49564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Gorgrond!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Yrel in Gorgrond zu melden.\n\nYrel und Maraad wollen eine kleine Expedition in die Wildnis von Gorgrond entsenden.\n\nWir hoffen, auf diese Weise das Land besser kennenzulernen und vielleicht eine der Schwächen der Eisernen Horde auszumachen.\n\nUnterstützt ihre Expedition.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Yrel in Gorgrond.", completion = "Willkommen in Gorgrond, Kommandant.\n\nWir sind selbst gerade erst angekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49565] = { id = 49565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Talador!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Vorarbeiter Eksos in Talador zu melden.\n\nDie Eiserne Horde will Talador übernehmen. Die Gegend ist perfekt geeignet, um schnell und widerstandslos Verstärkung in jeden anderen Teil von Draenor zu entsenden.\n\nVorarbeiter Eksos errichtet zurzeit einen Außenposten in Talador. Reist dorthin und haltet die Eiserne Horde auf.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Vorarbeiter Eksos in Talador.", completion = "Es ist schön, Euch zu sehen, Kommandant {name}. Ich könnte Euren Rat brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49566] = { id = 49566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Spitzen von Arak!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Azik in den Spitzen von Arak zu melden.\n\nEs wurde gemeldet, dass flügellose Arakkoa aus den Spitzen von Arak fliehen. Gerüchten zufolge fliehen sie vor einer Superwaffe der Eisernen Horde.\n\nWir müssen herausfinden, warum sie ihre Heimat verlassen und was mit ihren Flügeln geschehen ist.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Azik in den Spitzen von Arak.", completion = "<Azik mustert Euch von oben bis unten.>\n\nAzik könnte wetten, dass Ihr bei Eurem Volk jemand Wichtiges seid.\n\nKommt doch näher. Azik könnte Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49567] = { id = 49567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Nagrand!", description = "Alle tauglichen Mitglieder der Allianz sind angehalten, sich umgehend bei Leutnant Balfor in Nagrand auf Draenor zu melden.\n\nYrel schlägt vor, dass die Allianz einen Außenposten in Nagrand einrichtet, um unseren Kampf gegen den Kriegshymnenklan zu unterstützen.\n\nSichert Euch einen Flug nach Nagrand und trefft Euch mit Leutnant Balfor und der Versorgungskarawane.\n\nRuhm der Allianz!", sourceObjective = "Sprecht mit Leutnant Balfor in Nagrand auf Draenor.", completion = "Sie kamen... aus dem... Nichts.\n\n<Der Leutnant wird fast ohnmächtig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49569] = { id = 49569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unten am Fluss", description = "Wir bekomm' Hilfe von Krag'wa und dem Goblintrupp. Wir müssen zurück nach Zul'jan und unsren Plan umsetz'n, um die Bluttrolle aufzuhalt'n.\n\nAllerdings gibt's da ein Problem. Der Goblintrupp kann seinen Mech nich' schnell genug durch den Dschungel transportier'n. Wir müss'n ihn per Boot befördern.\n\nWir beide werd'n sie begleiten und dafür sorg'n, dass die Bluttrolle den Mech nich' zerstör'n.\n\nIch geh schon voraus und mach das Boot am Flussufer startklar. Trefft uns dort.", sourceObjective = "Segelt mit Talanji den Fluss hinab und verteidigt den A.M.O.D. des Goblintrupps.", completion = "So weit, so gut, {name}. Nun zum schwierig'n Teil. Bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[49570] = { id = 49570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein steiniger Start", description = "<Beim Durchblättern des Buches fällt Euch auf, dass die Seiten ungewöhnlich dick und auf ihrer Oberfläche runenförmige Juwelen eingesetzt sind. Samuel Kaltmann bemerkt Euren Blick und kommt näher.>\n\nAh, diesen Schatz besitze ich schon seit vielen Jahren. Wunderschön, nicht wahr? Ich weiß nicht, was da steht, doch schon der Gedanke, dass dort etwas in Juwelen niedergeschrieben steht, lässt mein Herz jedes Mal höherschlagen.\n\nWenn ich es mir recht überlege, könnte Zooey Tintenritzel das vielleicht entschlüsseln. Sagt, {name}, könntet Ihr es zu ihr bringen und fragen, ob sie es übersetzen kann?", sourceObjective = "Bringt das Buch zu Zooey Tintenritzel und fragt sie, ob sie den Text übersetzen kann.\n\nBereitgestellter Gegenstand:", completion = "J-Ja? Kann ich Euch helfen?\n\n<Ihr übergebt Zooey das Buch und fragt sie, ob sie es übersetzen kann. Während sie die einzelnen Seiten umblättert, bemerkt Ihr die erstaunten Gesichtsausdrücke der Inschriftenkundlerin.>\n\nMeine Güte, ich habe bislang nur von der Existenz dieser Bücher gehört, habe aber noch nie eines aus der Nähe gesehen. Wisst Ihr, was das ist?\n\nEs ist Altirdisch. Dieses Buch muss Jahrhunderte alt sein!\n\nNatürlich helfe ich, es zu übersetzen! Nur... na ja... mein Altirdisch ist nicht so gut. Ich werde einiges Referenzmaterial benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49571] = { id = 49571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit durchgraben", description = "Mal überlegen: Jana Hafner hat ihr Buch zu uralten Runen und Schriften wahrscheinlich noch. Und ich glaube, dass Tal'ana einige Schriftrollen besitzt, die er in Ulduar gefunden hat.\n\nOH! Und Toopa hat auf seiner letzten Reise etwas gefunden, das eine Art Kodex zu sein scheint. Ich weiß noch, dass Runen darauf waren, die denen in diesem Buch verblüffend ähnlich sehen.\n\nWenn Ihr sie überreden könnt, uns ihr Material für eine Weile... ähm... auszuleihen, könnte ich Euch damit vielleicht eine Übersetzung erstellen. Ihr müsst mich dafür noch nicht einmal bezahlen!", sourceObjective = "Bittet Jana Hafner um ihr Buch \"Urvölker: Runen und Schriften\". Bittet Tal'ana um seine Schriftrollen des Steinvaters. Und bittet Toopa um den Dungardkodex.", progress = "Wie läuft es mit der Übersetzung?", completion = "Konnte sie es übersetzen?\n\n<Ihr übergebt Samuel das Buch und er beginnt, es zu lesen.>\n\nDas ist unglaublich. Dieser Irdene konnte an bestimmten von ihm gebauten Schreinen aus Licht Juwelen erschaffen. Ich meine, er schreibt, dass er auf der ganzen Welt mehrere davon gebaut hat, aber...\n\n<Samuel holt ein paar Karten hervor und überfliegt sie.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49572] = { id = 49572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein der See", description = "Der nächste Schrein befindet sich gleich hier im Tiragardesund.\n\nIm Tagebuch erwähnt der Irdene, dass er hier bläulich gefärbte Juwelen erschaffen hat. Ich frage mich, ob sie irgendwie dem Kyanit ähneln, den es hier gibt.\n\nSeht nach, ob der Schrein noch existiert. Hoffentlich ist er noch in brauchbarem Zustand.\n\nIch werde das Tagebuch weiter studieren, Vielleicht finde ich noch ein paar nützliche Hinweise.", sourceObjective = "Untersucht den Schrein der See im Tiragardesund.", completion = "<Beim Betrachten des Schreins vor Euch müsst Ihr seine faszinierende Bauweise einfach bewundern.\n\nDie nahtlose Konstruktion zeigt ein Strahlenmuster aus azurblauen Edelsteinen, die an einem einzelnen Punkt zusammenlaufen.\n\nAn einem einzelnen leeren Punkt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49573] = { id = 49573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein der Abendflut", description = "Es gibt hier in Kul Tiras noch zwei weitere Schreine.\n\nIch glaube. der nächste befindet sich in Drustvar, nahe der Rauhügelmine, südöstlich von Korlach.\n\nHier sind die Notizen zu dem Standort. Sollte auch dieser Schrein ausgebessert werden müssen, bin ich mir sicher, dass Ihr ihn mit Eurem Können im Umgang mit Juwelen leicht reparieren könnt.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und untersucht den Schrein in Drustvar. Falls eine Reparatur nötig ist, tut Euer Bestes, dies zu bewerkstelligen.", completion = "<Bei der Untersuchung des Schreins bemerkt Ihr, dass mehrere der in die Oberfläche eingesetzten Juwelen zerbrochen sind und ausgetauscht werden müssen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49574] = { id = 49574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein der Stürme", description = "Ja, ich denke, hier in Kul Tiras müsste es ein paar von ihnen geben. Ihr solltet ihnen einen Besuch abstatten, {name}, und sie aus der Nähe anschauen. Dann seht Ihr, ob dieses Buch die Wahrheit sagt.\n\nDer Schrein, den er hier erwähnt, könnte sich im Sturmsangtal in der Nähe von Brennadam befinden.\n\nIhr solltet ihn schnell finden können, da er nur ein kurzes Stück von Brennadam aus in nördlicher Richtung liegt.\n\nHier sind die Notizen zu dem Schrein. Ich habe seinen Standort auf Eurer Karte markiert. Viel Glück, {name}.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und untersucht den Schrein im Sturmsangtal. Falls eine Reparatur nötig ist, tut Euer Bestes, dies zu bewerkstelligen.", completion = "<Bei Eurer Untersuchung bemerkt Ihr, dass der Schrein mehrere Stellen aufweist, an denen früher offenbar Juwelen angebracht waren.\n\nZudem scheint das Juwel in der Mitte bereits einige Risse aufzuweisen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49575] = { id = 49575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Juwel der Gezeiten", description = "<Ihr seid überzeugt, dass hier etwas fehlt. Rasch sucht Ihr den Bereich nach etwas Passendem ab, doch ohne Erfolg.\n\nAber ein Betrunkener macht hier am Schrein mit seinem Gegröle auf sich aufmerksam. Vielleicht weiß er etwas über den Verbleib des fehlenden Teils.>", sourceObjective = "Sprecht mit dem \"Aalglatten\" Johann und versucht, etwas über das fehlende Herzstück in Erfahrung zu bringen.", progress = "<Vielleicht kommt Ihr ja hinter die Funktionsweise des Schreins, wenn Ihr das fehlende Herzstück entdeckt?>", completion = "<Als Ihr den Edelstein wieder in der Mitte des Schreins befestigt, entspringt diesem ein merkwürdiger Impuls.\n\nDer wiederhergestellte Schrein beginnt, vor Energie zu summen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49576] = { id = 49576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhensondierung", description = "<Eure Notizen legen nahe, dass der Irdene die Juwelen aus Erdelementaren im Süden extrahiert hat.\n\nNach einem Blick auf Eure Karte fragt Ihr Euch, ob er die heutigen Ruinen einer einst uralten Siedlung meinte, die jetzt mit Konstrukten und Untoten übersäht ist.\n\nVielleicht findet Ihr dort Hinweise darüber, wo Ihr diese Juwelen findet.>", sourceObjective = "Untersucht Gol Osigr auf Hinweise zu den Juwelen, mit denen der Schrein gebaut wurde.", progress = "<Es müssen definitiv alle zerbrochenen Juwelen ausgetauscht werden.>", completion = "<Ihr beginnt, alle zerbrochenen Juwelen vom Schrein zu entfernen und die neuen vorsichtig einzusetzen.\n\nAls Ihr das letzte einsetzt, entweicht dem Schrein ein Impuls und es scheint, als würde er das Licht aus der Umgebung in sich hineinziehen.\n\nDas merkwürdige Leuchten, das vom Inneren des Schreins ausgeht, lässt Euch vermuten, dass er wieder aktiv ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49577] = { id = 49577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter der Oberfläche", description = "<In Euren Notizen lest Ihr, dass der Irdene die Juwelen in einem nahen Berg im Nordwesten abgebaut hat.\n\nVielleicht könnt Ihr den Boden dieses Gebiets sondieren, um mehr von den Juwelen zu finden und den Schrein wiederherzustellen.>", sourceObjective = "Geht zu den Windgeschorenen Hügeln und sammelt 20 Goldberyllsplitter.", progress = "<Die Juwelen an diesem Schrein wurden auf ziemlich komplizierte Weise angeordnet.>", completion = "<Ihr bringt die Juwelen vorsichtig mit Euren Werkzeugen in die richtige Form und befestigt sie an den leeren Plätzen am Schrein.\n\nMit den übrigen Juwelen gelingt es Euch, die Risse im Edelstein in der Mitte so auszubessern, dass er schließlich wieder über eine glatte Oberfläche verfügt.\n\nAls Ihr das letzte Juwel platziert, entweicht dem Schrein ein Energieimpuls und es scheint, als würde er das Licht aus der Umgebung in sich hineinziehen. Das merkwürdige Leuchten, das vom Inneren des Schreins ausgeht, lässt Euch vermuten, dass er wieder aktiv ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49578] = { id = 49578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Ich war schon einmal in Zandalar. Es ist ein verrückter Ort voller Dinosaurier und anderer unsäglicher Bestien. Und der Standort einer der Schreine, der in dem Tagebuch erwähnt wird, klingt wie der Ort, den man Vol'dun nennt.\n\nEs ist eine unheilvolle Wüste voller Schluchten, in deren Zentrum eine große Pyramide steht.\n\nWenn meine Berechnungen stimmen, muss sich der Schrein in diesem Gebiet befinden. Ich werde ihn für Euch auf Eurer Karte markieren.\n\nUnd lasst uns hoffen, dass er noch intakt ist.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und untersucht den Schrein in Vol'dun. Falls eine Reparatur nötig ist, tut Euer Bestes, dies zu bewerkstelligen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49579] = { id = 49579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Der nächste Schrein könnte etwas schwierig zu erreichen sein. Er befindet sich in Zandalar, dem Herzen des Trollreiches.\n\nNun, vielleicht nicht in der Hauptstadt selbst, aber in ihrer Nähe. Genau genommen...\n\n<Samuel blickt auf die vor ihm ausgebreitete Karte.>\n\nAh, er liegt nicht weit entfernt von (POI). Ich hörte, dass es dort einige Streitereien zwischen Horde und Allianz gegeben hat. Vielleicht gibt es ja dort ein Lager, das Ihr als Ausgangspunkt nutzen könnt.\n\nHier sind einige Notizen über den Schrein. Seinen Standort habe ich für Euch auf Eurer Karte markiert.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und untersucht den Schrein in Zandalar. Falls eine Reparatur nötig ist, tut Euer Bestes, dies zu bewerkstelligen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49580] = { id = 49580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Der letzte Schrein befindet sich in Nazmir, in einem Sumpf, der von todbringenden Kreaturen bevölkert wird und die Heimat der Bluttrolle ist.\n\nZum Glück gab mir ein Verbündeter eine ziemlich detaillierte Karte dieser Region und wenn meine Berechnungen stimmen...\n\n<Samuel blickt hastig zwischen Tagebuch und Karte hin und her. Dann hält sein Finger schließlich über der Karte inne.>\n\nEs müsste genau hier sein. Merkt Euch diesen Standort. Hier sind die Notizen über diesen Schrein. Viel Glück, {name}.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und untersucht den Schrein in Nazmir. Falls eine Reparatur nötig ist, tut Euer Bestes, dies zu bewerkstelligen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49581] = { id = 49581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnengesprenkelte Dünen", description = "<In Euren Notizen steht, dass der Irdene an Dünen vorbeikam, in denen orangefarbene Edelsteine verstreut lagen, die ihn an das sanfte Sonnenlicht in dieser Gegend erinnerten.\n\nLaut Euren Notizen sollten sich diese Dünen südlich Eurer derzeitigen Position befinden.>", sourceObjective = "Begebt Euch zu dem auf Eurer Karte markierten Ort, an dem Ihr die Edelsteine vermutet, und sammelt 8 von ihnen. Schleift und poliert sie, wenn Ihr genug gesammelt habt.", progress = "<Diese Edelsteine haben eine sehr robuste Struktur. Die Zeit und auch der Wind müssen trotzdem ihren Tribut von ihnen gefordert haben.>", completion = "<Vorsichtig entfernt Ihr die alten, verwitterten Edelsteine aus dem Schrein und ersetzt sie mit den von Euch polierten.\n\nAls Ihr den letzten Stein einsetzt, entweicht dem Schrein ein Energieimpuls und es scheint, als würde er das Licht aus der Umgebung in sich hineinziehen. Das merkwürdige Leuchten, das vom Inneren des Schreins ausgeht, lässt Euch vermuten, dass er wieder aktiv ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49582] = { id = 49582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Nicht alles, was glänzt...", description = "<Ihr seht in Euren Notizen über den Schrein nach und erfahrt, dass dieser Edelstein aus einem \"goldenen Refugium\" stammt.\n\nAusgehend von Eurem Standort kann damit nur Atal'Dazar gemeint sein. Vielleicht könnt Ihr in dieser uralten Stadt einen Ersatz finden.>", sourceObjective = "Reist nach Atal'Dazar und sucht einen Ersatz für das zerbrochene Juwel.", progress = "<Nachdem Ihr den zentralen Edelstein ausgetauscht habt, denkt Ihr, dass Ihr den alten vielleicht noch verkaufen könnt.>", completion = "<Ihr kehrt zurück zum Schrein und beginnt, den alten Edelstein aus seinem Sockel zu entfernen. Dabei bricht er erneut und zersplittert in Euren Händen.\n\nDie Steine sind offensichtlich sehr viel zerbrechlicher, als Ihr anfangs gedacht hattet.\n\nMit größter Vorsicht fügt Ihr das Juwel, das Ihr gefunden habt, in den Sockel ein.\n\nAls Ihr den letzten Edelstein einsetzt, entweicht auch diesem Schrein der vertraute Impuls und das Leuchten, das von ihm ausgeht, versichert Euch, dass er wiederhergestellt ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49583] = { id = 49583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus Alt mach Neu", description = "<Offensichtlich hat die Zeit aber ihre Spuren an ihnen hinterlassen. Einige sind stellenweise zerfressen und abgeplatzt.\n\nDie Reparatur des Schreins könnte sich tatsächlich als einfach erweisen: ein simpler Austausch der alten Edelsteine gegen neue desselben Typs und Schliffs.>", sourceObjective = "Schleift 4 treibende Granate und tauscht die alten gegen neue aus.", progress = "<Ihr findet es interessant, dass der Schliff so ähnlich ist, und Ihr fragt Euch, wie das Design die ganzen Jahre überdauern konnte.>", completion = "<Beim Austausch passen alle neuen Edelsteine perfekt in die Sockel, was Eure Vermutung über ihre Ähnlichkeit bestätigt.\n\nSobald Ihr ihn befestigt habt, geht ein friedliches Leuchten vom Schrein aus. Dies lässt Euch vermuten, dass er wieder aktiv ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49584] = { id = 49584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das fehlende Kapitel", description = "<Samuel legt das Tagebuch hin und sieht zu Euch hinauf.>\n\nAls ich versucht habe herauszufinden, wo der Schrein ist, bin ich auf einen Eintrag gestoßen, der beschreibt, wie er eine Gegend erkundet, die von der Beschreibung her auf die Düstermarschen passt.\n\nEr beschreibt, wie er dort etwas sehr Wichtiges versteckt.\n\nBedenkt man, vor wie langer Zeit der Irdene in Azeroth gelebt hat, mag es weit hergeholt sein, aber vielleicht entdeckt Ihr ja etwas, wenn Ihr seinen letzten Schritten folgt.\n\nIch markiere den Ort auf Eurer Karte.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und seht, ob Ihr etwas in Erfahrung bringen könnt.", progress = "Wer weiß, was Ihr da draußen finden werdet. Hoffentlich irgendetwas...", completion = "Habt Ihr etwas gefunden?\n\n<Ihr überreicht Samuel das letzte Kapitel und dessen Abschrift. Beim Lesen entdeckt er mit großen Augen eine Seite mit dem Bauplan für die Linse.>\n\nIhr habt es gefunden, {name}! Jetzt können wir die Linse bauen und mit den Schreinen nutzen.\n\nNatürlich sind die Materialien für den Bau ziemlich... selten. Dennoch, Ihr habt es geschafft!\n\nEs war mir eine Ehre, hierbei mit Euch zusammenarbeiten zu dürfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49585] = { id = 49585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein steiniger Start", description = "<Beim Durchblättern des Buches seht Ihr seltsam wirkende, aus Juwelen geschliffene Runen, die in die steinernen Seiten eingebettet sind. Seshuli bemerkt Euren Blick und kommt näher.>\n\nAh, dies'n Schatz besitz ich schon seit viel'n Jahr'n. Wunderschön, nich' wahr? Keine Ahnung, was da steht, doch wenn ich dran denk, dass da was in Juwelen steht, schlägt mein Herz jedes Mal höher.\n\nWo ich so drüber nachdenk, kann es Grazzul vielleicht rauskrieg'n. Sagt ma', {name}, könnt Ihr es zu ihm bring'n und frag'n, ob er's übersetz'n kann?", sourceObjective = "Bringt das Buch zu Grazzul und fragt, ob er den Text übersetzen kann.\n\nBereitgestellter Gegenstand:", completion = "Womit kann ich helf'n?\n\n<Ihr übergebt Grazzul das Buch und fragt, ob er es übersetzen kann. Während er die einzelnen Seiten umblättert, bemerkt Ihr den erstaunten Gesichtsausdruck des Inschriftenkundlers.>\n\nBislang hab ich nur von der Existenz dieser Bücher gehört, aber ich hab noch nie eins geseh'n. Wisst Ihr, was das is'?\n\nDas is' Altirdisch. Dieses Buch muss Jahrhunderte alt sein!\n\nNa klar helf ich, es zu übersetz'n! Aber... na ja... mein Altirdisch is' echt nich' so gut. Ich werd 'n paar Dinge dafür brauch'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49586] = { id = 49586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit durchgraben", description = "Mal überleg'n: Forscherin Alerinda hat ihr Buch über uralte Runen und Schrift'n wahrscheinlich noch. Und ich glaub', dass Koatini einige Schriftroll'n besitzt, die er in Ulduar gefund'n hat.\n\nOH! Und Chronist Schoopa hat auf seiner letzt'n Reise 'ne Art Kodex gefund'n. Ich weiß noch, dass da Runen drauf war'n, die denen in dies'm Buch total ähnlich sah'n.\n\nWenn Ihr sie überred'n könnt, uns ihr Material für 'ne Weile auszuleih'n, könnt' ich Euch damit wahrscheinlich 'ne Übersetzung erstell'n.", sourceObjective = "Bittet Forscherin Alerinda um ihr Buch \"Urvölker: Runen und Schriften\". Bittet Koatini um seine Schriftrollen des Steinvaters. Und bittet Chronist Schoopa um den Dungardkodex.", progress = "Wie läuft's mit der Übersetzung?", completion = "Konnt' er's übersetz'n?\n\n<Ihr übergebt Seshuli das Buch und sie beginnt zu lesen.>\n\nDas is' ja unglaublich! Dieser Irdene konnt' aus Licht Juwelen erschaff'n. Und erst die Schreine, die er gebaut hat, ich mein, er schreibt, dass er mehrere davon gebaut hat, aber...\n\n<Seshuli holt ein paar Karten hervor und überfliegt sie.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49587] = { id = 49587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein der Natur", description = "Ein weiterer Schrein existiert hier in Zuldazar.\n\nOh, und hier hab ich noch 'n paar Notizen über den Schrein aufgeschrieb'n. Im Tagebuch redet der Irdene davon, grün gefärbte Juwelen zu erschaff'n. Ich frag' mich, ob sie ähnlich sin' wie das Viridium, das wir in dem Erz find'n, das wir abbau'n.\n\nGeht ma' nachseh'n, ob der Schrein noch steht. Hoffentlich können wir ihn noch nutz'n.\n\nIch werd das Tagebuch weiter studier'n und schau'n, ob ich noch mehr herausfind'n kann.", sourceObjective = "Untersucht den Schrein der Natur in Zuldazar.", completion = "<Während Ihr den Schrein betrachtet, wird Euch klar, dass das zentrale Juwel schwer beschädigt ist und ersetzt werden muss.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49588] = { id = 49588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein der Sande", description = "Es gibt hier in Zandalar noch zwei and're Schreine. Der nächste is' in Vol'dun, nahe der Knochensplitterschlucht. Hoffentlich ham die Treulos'n den Schrein noch nich' besudelt.\n\nHier sin' die Notizen zu dem Standort. Wenn der Schrein auch ausgebessert werd'n muss, bin ich mir sicher, dass Ihr ihn mit Eurer Juwelierskunst leicht reparier'n könnt.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und untersucht den Schrein in Vol'dun. Falls eine Reparatur nötig ist, tut Euer Bestes, dies zu bewerkstelligen.", completion = "<Beim Untersuchen des Schreins vermutet Ihr, dass es der sandige Wind in diesem Gebiet gewesen sein muss, der den eingesetzten Edelsteinen so zugesetzt hat, dass einige nun merkwürdige Formen und Risse aufweisen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49589] = { id = 49589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein der Dämmerung", description = "Ja, ich glaub', hier in Zandalar gibt es 'n paar. Ihr solltet sie such'n geh'n, {name}, und aus der Nähe anschau'n. Mal seh'n, ob dieses Buch die Wahrheit sagt.\n\nEs klingt so, als wenn dieser Schrein hier in Nazmir steht. Wenn meine Berechnungen stimm'n, is er' nich' weit südlich von Torgas Ruh.\n\nDieser Loa war ziemlich mächtig. Es is' wirklich traurig, dass er nich' mehr bei uns is'.\n\nHier sin' die Notizen für den Schrein. Ich hab den Standort auf Eurer Karte markiert. Mög'n die Loa mit Euch sein, {name}.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und untersucht den Schrein in Nazmir. Falls eine Reparatur nötig ist, tut Euer Bestes, dies zu bewerkstelligen.", completion = "<Bei der Untersuchung des Schreins bemerkt Ihr etwas, das Euch... vertraut erscheint. Der Schliff der Edelsteine wirkt wie eine primitive oder einfache Version der Art, wie Ihr Granat zu schleifen gelernt habt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49590] = { id = 49590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Ihr blickt von einem Edelstein zum nächsten und obwohl der Schrein instand gesetzt wirkt, strahlt er noch keine Energie ab.\n\nIhr holt Euer Juwelierswerkzeug hervor, untersucht den zentralen Stein und entdeckt tatsächlich einen Makel. Ein kleiner Riss zieht sich von der Unterseite aus nach hinten durch das Juwel.\n\nIhr seht in Euren Notizen über den Schrein nach und erfahrt, dass dieser Edelstein aus einem \"goldenen Refugium\" stammt.\n\nVielleicht weiß jemand im Lager der Forscherliga, was das bedeutet.", sourceObjective = "Reist zum Lager der Archäologischen Akademie und fragt nach dem \"goldenen Refugium\". Sucht nach einem Ersatzedelstein, sobald Ihr erfahren habt, wo es sich befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[49592] = { id = 49592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Bei der Untersuchung des Schreins bemerkt Ihr etwas, das Euch... vertraut erscheint. Der Schliff der Edelsteine wirkt wie eine primitive oder einfache Version der Art, wie Ihr Granat zu schleifen gelernt habt.\n\nOffensichtlich hat die Zeit aber ihre Spuren an ihnen hinterlassen. Einige sind stellenweise zerfressen und abgeplatzt.\n\nDie Reparatur des Schreins könnte sich tatsächlich als einfach erweisen: ein simpler Austausch der alten Edelsteine gegen neue desselben Typs und Schliffs." }
quests[49593] = { id = 49593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Ich war schon ma' in Kul Tiras. Die Menschen da sin' nich' gerade freundlich zu uns Zandalari. Aber dort, im Tiragardesund, liegt einer der Schreine.\n\nDort findet man mehr Menschen als irgendwo sonst im Land. Da müsst Ihr gut auf Euch aufpass'n, {name}.\n\nIch markier' den Standort auf Eurer Karte.\n\nUnd lasst uns hoff'n, dass die Menschen nix damit angestellt ham.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und untersucht den Schrein im Tiragardesund. Falls eine Reparatur nötig ist, tut Euer Bestes, dies zu bewerkstelligen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49594] = { id = 49594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Der nächste Schrein befindet sich an 'nem Ort namens Drustvar. Was ich so hör, soll's da jede Menge Hex'n geb'n.\n\nSie nutz'n Magie, um Dinge zum Leben zu erweck'n. Aber wenn ich so auf die Karte gucke, wo ich den Schrein vermute, müsst Ihr denen vielleicht gar nicht über'n Weg lauf'n.\n\nDer Schrein müsste ziemlich nah bei der Schmugglerhöhle steh'n. Ich würd da hingeh'n und den Schrein such'n. Ich markier die Stelle, an der ich ihn vermute, auf Eurer Karte.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und untersucht den Schrein in Drustvar. Falls eine Reparatur nötig ist, tut Euer Bestes, dies zu bewerkstelligen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49595] = { id = 49595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Der letzte Schrein in Kul Tiras befindet sich an 'nem grünen Fleck, den sie Sturmsangtal nenn'. Die Menschen dort werd'n Euch keine Probleme bereit'n.\n\nAber der Schrein liegt in der Mitte des Landes, also erwartet Euch 'ne lange Reise. Ich werd es Euch auf der Karte markier'n.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und untersucht den Schrein im Sturmsangtal. Falls eine Reparatur nötig ist, tut Euer Bestes, dies zu bewerkstelligen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49596] = { id = 49596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Beim Betrachten des Steinaltars vor Euch müsst Ihr seine faszinierende Bauweise einfach bewundern. Die nahtlose Konstruktion zeigt ein Strahlenmuster aus azurblauen Edelsteinen, die an einem einzelnen Punkt zusammenlaufen.\n\nAn einem einzelnen leeren Punkt. Ihr seid überzeugt, dass hier etwas fehlt. Rasch sucht Ihr den Bereich nach etwas Passendem ab, doch ohne Erfolg.\n\nUnterdessen ist jedoch jemand erschienen, der zuvor nicht da war. Vielleicht weiß er etwas über den Verbleib des fehlenden Teils.", sourceObjective = "Sprecht mit dem \"Aalglatten\" Johann und versucht, etwas über das fehlende Herzstück in Erfahrung zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49597] = { id = 49597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME" }
quests[49598] = { id = 49598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Bei Eurer Untersuchung bemerkt Ihr, dass der Schrein mehrere Stellen aufweist, an denen früher offenbar Juwelen angebracht waren. In Euren Notizen lest Ihr, dass der Irdene die Juwelen in einem nahen Berg im Norden abgebaut hat.\n\nVielleicht könnt Ihr den Boden dieses Gebiets sondieren, um mehr von den Juwelen zu finden." }
quests[49599] = { id = 49599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das fehlende Kapitel", description = "<Seshuli legt das Tagebuch aus der Hand und sieht zu Euch hinauf.>\n\nAlso, ich hab' versucht, zu bestimm'n, wo sich die Schreine befind'n. Dabei bin ich über 'nen Eintrag gestolpert, der von 'ner Erkundung in 'nem Gebiet berichtet, bei dem es sich um die Düstermarschen hand'ln könnte.\n\nWird vermutlich nichts bring'n, schließlich is' es lange her, dass der Irdene Azeroth durchwandert hat, aber vielleicht entdeckt Ihr ja was, wenn Ihr seinen letzt'n Schritten folgt.\n\nIch markiere seinen letzten Standort auf Eurer Karte.", sourceObjective = "Reist zum Ort, der auf Eurer Karte markiert ist, und seht, ob Ihr etwas in Erfahrung bringen könnt.", progress = "Wer weiß, was Ihr dort draußen entdeck'n werdet. Hoffentlich irgendwas...", completion = "Habt Ihr was gefunden?\n\n<Ihr überreicht Seshuli das letzte Kapitel und dessen Abschrift. Beim Lesen entdeckt sie eine Seite mit dem Bauplan für die Linse und ihre Augen öffnen sich weit.>\n\nIhr habt sie gefund'n, {name}! Jetzt können wir die Linse fertig'n un' bei den Schreinen nutz'n.\n\nNatürlich sin' die Materialen zur Fertigung recht... selten. Dennoch, Ihr habt's geschafft!\n\nEs is' mir eine Ehre, Euch bei dieser Arbeit zu unterstütz'n, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49613] = { id = 49613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silbermond", description = "Die Nachtgeborenen sind für Tausende von Jahren von der Welt isoliert gewesen. Jetzt, wo sie wieder aufgetaucht sind, ist es unsere Pflicht, sie auf den rechten Pfad zu bringen.\n\nDer Lordregent Theron hat sie zu einem Treffen mit uns in Silbermond eingeladen.\n\nKommt, {name}, lasst uns mit Thalyssra nach Silbermond reisen.", sourceObjective = "Trefft Euch mit Lady Liadrin in Silbermond.", completion = "Gut, wir sind alle da. Unsere Gäste sollten in Kürze eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49614] = { id = 49614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtgeborenen", description = "Der Kriegshäuptling wird mit unserem Erfolg zufrieden sein.\n\nIch bin mir sicher, dass Thalyssra und die Nachtgeborenen sich als starke Verbündete erweisen werden.", sourceObjective = "Kehrt zu Ji Feuerpfote in der Botschaft von Orgrimmar zurück, um das Ende dieser Geschichte zu hören.", completion = "Ihr habt gute Nachrichten mitgebracht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49615] = { id = 49615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Königs Vertrauen", description = "Jetzt, wo Ihr Euch 'n wenig eingelebt habt, redet Ihr am besten mit meinem Vater. Ihr findet ihn im Thronsaal auf seinem Thron, umringt von falsch'n Beratern, die zweifellos seinen Geist mit falschen Ratschlägen vergift'n.\n\nDer Aufzug hinter Euch bringt Euch direkt zum gold'nen Thron über uns.", sourceObjective = "Sprecht mit König Rastakhan am Goldenen Thron.", completion = "Ihr wart flink. Gut, denn ich könnte ein paar fähige Hände gebrauch'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49661] = { id = 49661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eier aus der Region", description = "Es gibt auf der Welt nichts Besseres, als ein Gericht, das aus frischen Zutaten gekocht wurde!\n\n{race}, ich befinde mich auf der Jagd! Einer Jagd nach den perfekten Eiern. Man hat mir von Aaleiern berichtet. Welch delikate Konsistenz... und dieses zarte Salzwasseraroma... Ich muss sie haben!\n\nDie einheimischen Aale legen ihre Eier an Land und kehren dann ins Meer zurück. Sammelt bitte diese Eier für mich, sodass ich ein deliziöses Omelett daraus zaubern kann!", sourceObjective = "Sammelt 10 Ringelschuppeneier aus Ringelschuppennestern.", sourceObjectiveStatus = "unverified-source-field" }
quests[49662] = { id = 49662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der fehlende Schlüssel", description = "Korthek ist im Laufe der Jahre gehässig und arrogant geworden, aber jetzt ist mir klar, dass er auch noch verrückt geworden ist.\n\nMythrax wird uns alle töten, wenn er freikommt.\n\nZu lange habe ich die Hoffnung genährt, dass ich Korthek friedlich davon überzeugen kann, seiner Ketzerei abzuschwören. Ich habe mich geirrt.\n\nGanz Zandalar ist in Gefahr, solange Korthek und seine Verbündeten auch nur einen einzigen Schlüssel zu Mythrax' Gefängnis besitzen.\n\nTrefft mich bei seiner Festung im Norden. Wir werden uns mit meinem alten Freund \"Imperator\" Korthek auseinandersetzen und gemeinsam dem Ganzen ein Ende bereiten.", sourceObjective = "Trefft Vorrik bei Bwoljins Sturz.", completion = "Hier draußen sind wir von Treulosen umgeben, {name}. Wir müssen schnell zuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49663] = { id = 49663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsche Prophezeiungen", description = "Jetzt, da dieses Ärgernis aus dem Weg geschafft is', kann ich mich wieder auf die Stadt konzentrieren. Zuldazar is' in meiner Abwesenheit schwach geworden.\n\nIhr solltet zu Rastakhan zurückkehr'n. Lasst den König wiss'n, dass sein Wille erfüllt und der falsche Prophet ausgelöscht wurde.\n\nWenn's Euch wichtig erscheint, solltet Ihr ihm vielleicht Vol'jambas Prophezeiung übermitteln. Aber ich glaub' nich', dass sie einen Unterschied mach'n wird.", sourceObjective = "Kehrt zu König Rastakhan in Dazar'alor zurück.", completion = "Vielleicht wird Zul in Zukunft im Kopf behalt'n, wo er sich einzuordnen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[49664] = { id = 49664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Anarchie verbündet", description = "Auch nach all diesen Jahren spüre ich hier die uralte Macht von Sethraliss. Mein Loa überdauert die Zeit.\n\nUns steht eine beachtliche Aufgabe bevor. Die werde ich nur mit klarem Verstand und viel Konzentration erfüllen können. Erlaubt mir, hier ein paar Minuten zu meditieren, wie ich es früher tat.\n\nIn der Zwischenzeit könntet Ihr den Vulpera dabei helfen, Ärger zu stiften. Die scheinen Euch ja zu kennen, und eine mächtige Störung würde die Treulosen sicher von unserer Mission ablenken.\n\nTrefft mich hier, wenn Ihr fertig seid. Dann werden wir gemeinsam fortfahren.", sourceObjective = "Sprecht mit Nisha.", completion = "{name}?! Wir müssen aufhören, uns an Orten wie diesem zu treffen.\n\nObwohl, wir sollten uns IMMER an Orten wie diesem treffen!\n\nHabt Ihr Lust, ein paar Treulose zu töten?", sourceObjectiveStatus = "unverified-source-field" }
quests[49665] = { id = 49665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruf zum Aufruhr", sourceObjective = "Befreit und bewaffnet 8 Vulperasklaven in Käfigen.", completion = "Seht, wie meine Leute kämpfen! Die Treulosen haben keine Chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[49666] = { id = 49666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie uns fürchten", description = "Ich trage dieses Banner mit in jede Schlacht, weil ich will, dass die Treulosen es fürchten lernen. Dass sie mein Volk fürchten lernen.\n\nWenn ich auf dem Schlachtfeld umgeben von den Treulosen falle, werde ich glücklich sterben.\n\nAn dem Tag werde ich weder eine Beerdigung noch Gebete brauchen. Aber ich werde jemanden brauchen, der mein Banner aufhebt und es in die nächste Schlacht trägt.\n\nWenn Ihr meine Auffassung teilt, steckt diese Banner in die Leichen jedes Treulosen, den Ihr tötet. Lasst die Überlebenden wissen, wer hinter ihnen her ist.", sourceObjective = "Steckt 12 Vulperabanner in tote Treulose.", completion = "Und das ist erst der Anfang! Jetzt wissen diese Treulosen, wer hinter ihnen her ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[49667] = { id = 49667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kleinen", sourceObjective = "Tötet Gutachterin Versik und führt die Vulperakinder zurück zu Meerah.", completion = "Danke, danke, danke!\n\nNiemand sollte je so viel Hass und Schmerz erleben müssen wie diese Kinder. Ich werde dafür sorgen, dass sie ebenso viel Liebe erhalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49668] = { id = 49668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlucht soll brennen", sourceObjective = "Zündet die Orte der Sklavenauktion in der Schlängelnden Schlucht an.", completion = "Die Feuer breiten sich schnell aus. Beeilen wir uns, solange die Treulosen noch abgelenkt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[49669] = { id = 49669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselt die Bestien", description = "Die Treulosen sind arrogante und raffgierige Kreaturen, die Leute entführen und Wildtiere fangen, die sie niemals wirklich zähmen können. Und all das nur, um ihre endlose Gier nach Krieg zu stillen.\n\nIch habe ihre Sklaventreiber sogar Bluttrolle und andere dunkle Monster aus den Sümpfen in Nazmir holen gesehen.\n\nAls ich dort vorne die Futtergruben ausspähte, hörte ich furchtbare Geräusche aus einer Höhle kommen.\n\nGanz gleich, welche Monster sie darin verbergen, versucht sie zu befreien, damit sie an den Treulosen Rache üben können.", sourceObjective = "Tötet Zähmer Traskniss, um die Kroggs freizulassen.", completion = "Kroggs sind gewalttätige, schmutzige Dinger... Noch ein Grund, Nazmir zu meiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49676] = { id = 49676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfgarderobe", description = "Kiro ist der Anführer meiner Karawane. Er war schon immer viel zu passiv.\n\nIch habe ihn gewarnt, dass wir einen Präventivschlag gegen die Sethrak führen müssen, aber er hat darauf bestanden, dass wir die Köpfe einziehen und weiterhin still und leise unseren Geschäften nachgehen.\n\nSeht, wo uns das hingeführt hat.\n\nUnsere Karawane war vollkommen unvorbereitet auf diesen Angriff.\n\nIch bin bereit, um für das, was uns gehört, zu kämpfen, aber ich bin nicht gerade passend für eine Schlacht gekleidet.\n\nHelft mir, hier unter unseren Feinden die passende Ausrüstung zu beschaffen. Wir werden ihre eigenen Werkzeuge gegen sie verwenden.", sourceObjective = "Helft Nisha, ein Kriegsbanner, einen Helm und Sprengstoff zu finden.", progress = "Den Gegner mit seinem eigenen Schwert zu töten, ist eine noch viel größere Erniedrigung, nicht wahr?", completion = "Jetzt sind wir bereit für eine echte Herausforderung!", sourceObjectiveStatus = "unverified-source-field" }
quests[49677] = { id = 49677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffspläne", description = "Bevor wir angegriffen wurden, hatte ich einen Plan für einen Angriff auf die Sethrak ausgearbeitet.\n\nEr wurde auf Grundlage einwandfreier Informationen geschmiedet. Das weiß ich, weil ich die Informationen selbst gesammelt habe.\n\nIch habe ihr ganzes Lager inspiziert und eine Karte nach meinen Erkenntnissen gezeichnet.\n\nMein Plan stützt sich auf diese Karte, aber sie befindet sich in den Händen von Giftzahnruferin Sraka, der Schlägerin, die den Sturmangriff auf meine Heimat leitet.\n\nHelft mir, sie zu töten, damit ich mein rechtmäßiges Eigentum zurückbekomme!", sourceObjective = "Holt Nishas Angriffspläne von Giftzahnruferin Sraka zurück.", progress = "Mein Angriffsplan ist sowohl detailliert als auch gefährlich.", completion = "Diese Pläne werden unser Schlüssel sein, den Kampf zu den Sethrak zu tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49678] = { id = 49678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie treiben es auf die Spitze", description = "Gut, dass Ihr gekomm' seid. Dol'watha wird von den Schlangenmenschen angegriff'n.\n\nDie sin' gekomm' und ham komische Spitzen ausm Boden gezog'n. Ich hab 'nen Haufen Schlangenmänner mit Federmützen gesehen, die von ihren Blitzen getroff'n werden und davon nich' sterben.\n\nWenn's für sie nich' schlecht is', isses für sie was Gutes. Und das is' übel für uns.\n\nZerstört die Spitzen. Hoffentlich lässt das ihr'n Vorteil schwind'n und wir könn' sie leichter töt'n.", sourceObjective = "Zerstört 4 Sethrakspitzen.", completion = "Jetz liegt nich' mehr so 'ne Spannung in der Luft. Das is' gut. Heißt, dass wir was richtig gemacht hab'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49679] = { id = 49679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sethrakinvasion", description = "Dol'watha is 'n kleines Dorf. Hat ein paar Höfe mit Tieren un' 'nen netten Blick auf den Sumpf.\n\nDarauf war'n wir nich' vorbereitet...\n\nDie Schlangenmenschen kam'n zu Hunderten aus dem Boden geschoss'n. ham meine Tiere, meine Familie, meine Freunde getötet. Die Erde begann zu beb'n un' schon sin' wir um unser Leben gerannt.\n\nIch hatte schon von den Schlangenwesen aus den Wüsten von Vol'dun gehört, doch ich hätt nie erwartet, die wirklich mal zu Gesicht zu krieg'n...\n\nHelft uns, sie zurückzuschlag'n. Tötet so viele wie möglich. So leicht gibt Dol'watha nich' klein bei!", sourceObjective = "Tötet 12 Sethrak in der Sandnarbenbresche.", completion = "Die Gefallenen komm'n dadurch zwar nich' zurück, aber es zeigt ihnen wenigstens, dass Dol'watha sich nich' ohne Kampf geschlag'n gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49680] = { id = 49680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelsruferin Soltok", description = "Als ob Schlangenmenschen mit Schwertern nich' genug wär'n, ham sie auch noch 'nen mächtigen Himmelsrufer im Schlepptau.\n\nMan sagt, die Himmelsrufer können große Stürme heraufbeschwör'n. Die Spitzen un' diese grellen Lichtblitze sin' deren Werk.\n\nEs gibt eine, deren Feder größer is' als die der anderen. Is' sicher ihre Anführerin. Sie nennt sich Soltok oder so... irgendwas Zischendes halt.\n\nAuch egal. Tötet sie.", sourceObjective = "Tötet Himmelsruferin Soltok.", completion = "Gut, sehr gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[49681] = { id = 49681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klein Tika", description = "<Der winzige gepanzerte Raptor kratzt kläglich an den hölzernen Latten des Käfigs. Als Ihr Euch nähert, zuckt das Reptil wild und kreischt durchdringend nach Hilfe!\n\nVielleicht könnt Ihr den Käfig öffnen und ihn freilassen.>", sourceObjective = "Rettet Klein Tika.", completion = "Warum is' sie voller Blut?\n\nWenn ich's mir recht überlege, sagt's mir lieber nich'.\n\nLoa sei Dank, dass die Kleine noch am Leben is'!", sourceObjectiveStatus = "unverified-source-field" }
quests[49694] = { id = 49694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissensdrust", description = "Es gibt überall Blutinschriftenmeister, die Euch das Nötige beibringen können. Als ersten der Meister solltet Ihr Kronah aufsuchen.\n\nSie ist ein bisschen... exzentrisch, um es milde auszudrücken. Sie gehört zu den wenigen Tortollanern, die ein wenig herumgekommen sind.\n\nSie hat mir den Blutvertrag beigebracht, den ich heraufbeschwören kann!\n\nSie hält sich gern in der Schmugglerhöhle an der Westküste von Drustvar auf. Oh, und könntet Ihr sie von mir grüßen, wenn Ihr sie seht?!", sourceObjective = "Sucht Kronah in der Schmugglerhöhle in Drustvar auf.", completion = "<Kronah betrachtet Euch argwöhnisch von Kopf bis Fuß.>\n\nSagt mal \"Ahhh\", Jungspund.\n\n<Kronah schaut sich Eure Mundhöhle an.>\n\nIhr habt da ein paar schöne Zähne. Dafür könnte man einen hübschen Preis verlangen. Aber deswegen seid Ihr nicht hier, oder?\n\nNein, Ihr gehört wohl eher zu den Leuten, die sich den Prüfungen der Blutverträge gewachsen fühlen, oder? Also gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[49698] = { id = 49698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lichtgeschmiedeten", description = "Interessiert es Euch, wie die Lichtgeschmiedeten Draenei der Allianz beigetreten sind? Das ist wohl eine meiner liebsten Geschichten.\n\nVermutlich, weil man dabei unsere wunderschöne Welt vom All aus sieht!\n\nAlles begann, als Hochexarch Turalyon Mitglieder der Allianz auf die Vindicaar eingeladen hat...", sourceObjective = "Reist zur Vindikaar.", completion = "Willkommen, {name}. Ihr werdet in Kürze ein Ritual erleben, das bisher den Mitgliedern der Armee des Lichts vorbehalten war.", sourceObjectiveStatus = "unverified-source-field" }
quests[49703] = { id = 49703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haus Sturmsang", description = "Ich fürchte, ich kann Euch leider nicht viel weiterhelfen. Ich bin in letzter Zeit nicht viel aus Brennadam herausgekommen.\n\nEs stimmt, was sie sagten: Die Miliz kommt jetzt nur noch in die Stadt, um ihre Rationen zu holen, anstatt die Händler zu beschützen oder die Stacheleber zu dezimieren.\n\nSie sagen immer, sie haben ihre Befehle, aber diese Befehle könnten nur von meinen Brüdern am Schrein kommen. Meine Brüder und ich haben geschworen, unseren Bürgern zu dienen... Das passt doch nicht zusammen.\n\nBruder Anderson ist in der Nähe, an der Seemannsrinne. Vielleicht weiß er mehr als ich.", sourceObjective = "Trefft Bruder Pike und Taelia an der Seemannsrinne.", completion = "Was ist nur mit unseren Leuten passiert...", sourceObjectiveStatus = "unverified-source-field" }
quests[49704] = { id = 49704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ernter außer Kontrolle", description = "Seht Ihr die Golems da unten? Die Bauern setzen ihre scharfen Greifer ein, um die Ernte einzuholen, aber diese sind modifiziert und fällen Bäume... \n\nDie brauchen sie hier doch gar nicht, wenn sie so viele Arbeiter haben, oder?\n\nIch glaube eher, die Miliz nutzt sie, um die eigenen Leute einzuschüchtern!\n\nVersucht, eine intakte Triebfeder von einem zu bekommen. Ich habe einige von ihnen in Boralus repariert. Ich sollte herausfinden können, wer an ihrer Mechanik herumpfuscht.", sourceObjective = "Beschafft eine nasse Triebfeder.", progress = "Hattet Ihr Erfolg? Die Triebfedern sind normalerweise spröde und gehen schnell kaputt.", completion = "Perfekt! Lasst mich mal einen genaueren Blick darauf werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49705] = { id = 49705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnötige Härten", description = "Lord Sturmsang war noch nie zimperlich, aber das geht zu weit. Die Arbeiter schuften sich zu Tode!\n\nAnderson war ein guter Mann. Diese Quälerei ist inakzeptabel.\n\nNehmt diese Phiole und verabreicht den Inhalt den Arbeitern. Sie ist gefüllt mit gesegnetem Meerwasser, das sie erfrischt und stärkt.\n\nGeht den Soldaten aus dem Weg, wenn Ihr könnt. Sie befolgen auch nur Befehle. Wir brauchen nicht noch mehr Tote.", sourceObjective = "Erfrischt 8 erschöpfte Arbeiter.", completion = "Wir haben hier viel harte Arbeit vor uns, aber sie darf keine Menschenleben kosten.", sourceObjectiveStatus = "unverified-source-field" }
quests[49706] = { id = 49706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proklamation - Information", description = "Mein Lord verlässt kaum unsere Ländereien entlang der Nordküste und Besucher sind strengstens verboten. Die Verbindung des Hauses zu den meisten anderen sind die Gezeitenweisen, wie ich einer bin.\n\nLord Sturmsang kommuniziert seine Befehle gewöhnlich über Proklamationen, die im ganzen Tal ausgehängt werden. Brennadam hat noch nie eine davon erreicht, aber wenn wir hier welche finden können, erfahren wir vielleicht mehr.", sourceObjective = "Lest 3 Proklamationen von Sturmsang.", progress = "Lord Sturmsang ist wohl ein wenig abgehoben, aber seine Macht über die Gezeiten ist unübertroffen.", completion = "Unabhängigkeit?!\n\nDas geht zu weit. Ein geteiltes Kul Tiras ist schwach und angreifbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[49710] = { id = 49710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiertanz", description = "Die Greifen werden von uns nicht nur eingefangen und gezähmt, sondern wir sorgen auch für ihren Erhalt.\n\nRettet die Eier, die Ihr in verlassenen Nestern in der Nähe findet. Legt sie in die neuen Nester, die wir für die vertriebenen Greifen errichtet haben. Ich bin mir sicher, dass ein Greifenweibchen die Eier akzeptieren wird.", sourceObjective = "Sammelt 4 gefleckte Greifeneier.", progress = "Findet ein sicheres Nest.", completion = "Die Eier passen perfekt in die neuen Nester.", sourceObjectiveStatus = "unverified-source-field" }
quests[49715] = { id = 49715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in der Grausteinfeste", description = "Ein Freund von mir, auch ein Militärkurier, wurde zur Grausteinfeste geschickt. Das Fort liegt direkt außerhalb von Boralus und er sollte schon längst zurück sein.\n\nIch habe noch eine andere Aufgabe zu erledigen. Könntet Ihr vielleicht im Fort mal nach dem Rechten sehen? Vielleicht bilde ich mir das alles auch nur ein.", sourceObjective = "Sprecht mit Tallis Himmelsherz.", completion = "Ein Kurier? Den haben wir bei dem Aufstand verloren, glaube ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[49716] = { id = 49716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Vertrauen", description = "Die Männer in der Festung standen einst unter meinem Befehl, also muss ich mich jetzt um sie kümmern. Sie haben alle spezielle Dienstmarken dabei, mit denen wir sie identifizieren können. Bringt mir einige dieser Dienstmarken, als Beweis, dass Ihr sie aufgerieben habt.\n\nDiese Männer sind keine Soldaten von Boralus mehr. Und somit haben sie auch das Recht verloren, den Prachtmeeranker zu tragen.", sourceObjective = "Sammelt 8 Identifikationsmarken eines Marinesoldaten.", progress = "Habt Ihr die Dienstmarken dabei?", completion = "Was für eine hässliche Aufgabe, aber sie musste erledigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49719] = { id = 49719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahltag", description = "Jetzt, wo wir unsere Hände in Blut gewaschen haben, können wir wohl ins Lager zurückkehren.\n\nIch werde vorausgehen und Ihr könnt Euch hier noch weiter umschauen. Vergesst aber nicht, Eure Belohnung von Tagart zu holen.", sourceObjective = "Trefft Tagart im Lager der Raubeine.", completion = "Hier ist Euer Lohn. Ihr würdet ein gutes Raubein abgeben. Kommt zurück, wenn Ihr wieder Arbeit sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[49720] = { id = 49720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frei wie ein Vogel", description = "Himmelsherz hat mich hierhergebeten, um diesen Stadtjungs zu zeigen, wie man die hiesigen Fischadler zähmt. Einige meiner Schüler sind allerdings zu den Meuterern übergelaufen. Diese Möchtegernseemänner haben wohl vergessen, welche Strafe auf Verrat an den Drustvar steht.\n\nEs kommt noch schlimmer. Sie haben einige der jungen Vögel, die wir trainiert haben, eingesperrt. Ich habe hier mit den Raubvögeln alle Hände voll zu tun, also könntet Ihr bitte ein paar Jungvögel retten, wenn Ihr in der Festung seid? Ich wäre Euch sehr verbunden.", sourceObjective = "Befreit 5 junge Fischadler.", completion = "Meine gefiederten Freunde haben Besseres verdient als Partner, die ihr Land verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[49725] = { id = 49725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riskanter Plan", description = "Es ist schlimmer, als wir dachten. Sie werden Brennadam dem Erdboden gleichmachen!\n\nIn diesem Chaos bekommen wir nie eine Chance, mit Bruder Pike zu sprechen.\n\nIch habe eine Idee. Wenn sie allerdings schiefgeht, dann... Nun, ich hoffe, Ihr habt Eure Laufschuhe an.\n\nVertraut Ihr mir?", sourceObjective = "Treibt die Leute auseinander, die Bruder Pike bedrängen.", progress = "Was tragt Ihr da für ein Anhänger um Euren Hals?", completion = "Ah, Bruder Alen schickt Euch. Gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[49730] = { id = 49730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Donnerschnauze", description = "Donnerschnauze die Ebermatriarchin ist die größte ihrer Art im Tal. Sie richtet auf den nahe gelegenen Höfen und Feldern großen Schaden an.\n\nBürgermeisterin Rosen von Brennadam hat sogar ein Kopfgeld auf sie ausgesetzt.\n\nDonnerschnauze soll in der Nähe des Krals der Borstenrücken zu finden sein, also haltet nach Stachelebern Ausschau!", sourceObjective = "Bringt Donnerschnauzes Schnauze zu Bürgermeisterin Rosen.", progress = "Ja?", completion = "Mit dem Tod der Matriarchin wird sich die nächste Generation Eber verzögern. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[49731] = { id = 49731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzlicher Abschied", description = "Hier trenn' sich unsre Wege, {name}.\n\nIch werd den Namen Akunda trag'n un' hier 'n neues Leb'n anfang'n. \n\nRakera hat mir das Leb'n gerettet, un' ich will ab jetzt 'n Leb'n führ'n, was es auch wert war, gerettet zu werd'n. \n\nKönnt Ihr vielleicht diese Nachricht für mich übergeb'n, wenn Ihr ma' wieder in der Stadt seid? Ich vertrau drauf, dass Ihr sie nich' aufmacht, obwohl ich echt nich' glaub, dass Ihr meine Sauklaue überhaupt entziffern könnt.", sourceObjective = "Liefert Joraks Nachricht bei B'wizati in Zuldazar ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[49733] = { id = 49733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notdürftig zusammengeflickt", description = "Die meisten meiner Männer wurden verwundet, als sie aus der Festung flüchteten. Die wenigen, die unversehrt ankamen, wurden hier bei der Verteidigung verletzt.\n\n<Tallis übergibt Euch ein Bündel fleckiger Stofffetzen.>\n\nAll unsere hochwertigen Güter sind hinter diesen Mauern. Wir müssen das Beste aus den Gegebenheiten machen. Jeder Stofffetzen, der nicht von Soldaten getragen wird, wurde zu Verbänden verarbeitet. Wir haben aber nicht genug Leute, um uns um alle Verletzten zu kümmern.\n\nBitte helft uns und erneuert die Verbände von den schwer verletzen Soldaten.", sourceObjective = "Verbindet 5 verletzte Marinesoldaten.", completion = "Habt meinen Dank. Das sollte die Schmerzen einiger Soldaten lindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[49734] = { id = 49734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Meuterer meucheln", description = "Der Rädelsführer dieser Meuterei ist ein Mann namens Fernn. Er war schon immer unzufrieden mit dem Haus Prachtmeer und seiner Position hier. Aber die Männer zu hintergehen, mit denen er zusammenarbeitet, das hätte selbst ich nicht von ihm erwartet.\n\nTötet ihn und zeigt den Meuterern, dass es ein großer Fehler ist, sich mit wahrlich loyalen Marinesoldaten anzulegen.", sourceObjective = "Tötet Fernn den Abtrünnigen.", completion = "Gut gemacht. Das sollte reichen, um meine Männer zurück in die Festung zu bringen und sie wieder zu besetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49735] = { id = 49735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nestschutz", description = "Jetzt wo Tagart die Schikanen... äh, ich meine, Prüfungen beendet hat, könnt Ihr uns bei der Arbeit hier helfen.\n\nEinige der Greifennester in der Nähe wurden von Saurolisken überrannt. Wenn wir die Nester nicht schnell wieder freikämpfen, werden sich die Greifen wohl andere Nistplätze suchen.\n\nFolgt der Straße hoch zum Wasserfall und erledigt diese Saurolisken. Meldet Euch bei Sören, wenn die Aufgabe erfüllt ist. Er ist dort als Späher postiert.", sourceObjective = "Tötet 7 hungrige Tauschuppen.", completion = "Verdammte Saurolisken. Auf Nimmerwiedersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49736] = { id = 49736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Kul Tiras!", description = "Hört zu, ich will ehrlich zu Euch sein. Unsere Ränge hier sind nicht voll besetzt. Viele unserer Soldaten sind mit neuen Befehlen nach Boralus abgezogen.\n\nAls ob sie genau gewusst hätten, wann wir am schwächsten sind...\n\nAber wir schlagen zurück! Alle wehrfähigen Männer und Frauen der Stadt haben einen Verteidigungsposten bezogen.\n\nNehmt diese Schlachtstandarte und zeigt ihnen, wofür sie kämpfen!", sourceObjective = "Verwendet die Schlachtstandarte der Prachtmeers, um 15 Marinesoldaten der Wachkuppe oder Milizsoldaten zu ermutigen.", completion = "Es erfüllt mich mit Stolz, den Schlachtruf über das Schlachtfeld schallen zu hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[49737] = { id = 49737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftangriff", description = "Diese Piraten haben Luftunterstützung! Sie brennen unsere Höfe ab und lenken unsere Aufmerksamkeit von der Front weg.\n\nHolt sie vom Himmel!", sourceObjective = "Tötet 6 Himmelsreiter der Eisenfluträuber.", completion = "Sehr gute Arbeit! Ich werde Euch für eine Ehrenmedaille vorschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[49738] = { id = 49738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hände weg von meiner Beute!", description = "Wir haben es mit gesetz- und wertlosen Banditen zu tun. Kaum hatten sie an Boden gewonnen, da fingen sie auch schon mit dem Plündern an! Sie haben mitten in der Schlacht geplündert. Stellt Euch das nur mal vor!\n\nNun, wenn sie Beute haben müssen, dann sollen sie auch dafür bluten.\n\nBemannt die Hauptkanone oben auf der Wachkuppe und lasst das Höllenfeuer auf diese Schufte herabregnen!\n\nWeggetreten!", sourceObjective = "Bemannt die Kanone der Wachkuppe und tötet damit 20 Plünderer.", progress = "Worauf wartet Ihr? Geht dort hoch und bemannt die Kanone!", completion = "Sie haben die Hauptkanone zerstört?!\n\nDann wird es Zeit, dass wir zu Fuß vorrücken!", sourceObjectiveStatus = "unverified-source-field" }
quests[49739] = { id = 49739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind vor den Toren" }
quests[49740] = { id = 49740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer einstellen!", description = "Der Feind hat unsere eigenen Kanonen auf uns gerichtet.\n\nZerstört sie, damit die Bombardements aufhören!", sourceObjective = "Zerstört 4 eroberte Kanonen.", completion = "Kanonendonner kann Herzen mit Hoffnung oder mit Furcht erfüllen, je nachdem, auf welcher Seite man steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[49741] = { id = 49741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rechtmäßige Vergeltung", description = "Carsten hat mir beigebracht, wie man mit Gaunern, Schlägern und Abschaum wie Piraten umgeht.\n\nWenn sie uns angreifen, schlagen wir doppelt so hart zurück.\n\n<Taelias Hand schließt sich fest entschlossen um den Griff ihres Hammers.>\n\nUnd jetzt ist es Zeit, zurückzuschlagen.", sourceObjective = "Helft Taelia, das Piratenschiff an Daelins Tor zu vernichten.", completion = "Diese Feiglinge verstehen nur Härte. Wenn man ihnen zeigt, dass man kein leichtes Opfer ist, wenden sie sich ab und fliehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49744] = { id = 49744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombenklau", description = "Beim schaumigen Bart der See, das nenne ich eine Explosion!\n\nSie haben wohl Goblins angekarrt, und wenn ich eines über Goblins weiß, dann dass sie es lieben, Zeug in die Luft zu jagen.\n\nIch habe ein paar gesehen, die riesige Bomben getragen haben, und befürchte, die werden die Stadt hochgehen lassen. Die würde ich aber ganz gerne behalten. Also könntet Ihr bitte so viel Sprengstoff wie möglich von ihnen stehlen? Danach jagen wir ihre Verwüster in die Luft und stoppen dieses Höllenbombardement!", sourceObjective = "Beschafft 8 Sprengsätze der Horde und setzt sie gegen die Verwüster ein.", progress = "Vergesst nicht, auch in den Gebäuden nachzusehen!", completion = "Die sehen verflucht gefährlich aus. Ein Glück, dass sie uns nicht um die Ohren fliegen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49745] = { id = 49745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr habt deren Befehle", description = "Die Horde ist eine riesige Armee, vergesst das nicht. Und eine Armee braucht Befehle.\n\nIrgendjemand muss hier das Kommando haben. Jemand kennt den Plan und ich will ihn auch kennen.\n\nAchtet auf Personen, die nach Kommandobefugnis aussehen und versucht, Informationen dazu zu ergattern, was sie als Nächstes vorhaben.", sourceObjective = "Findet die Befehle des Kriegshäuptlings.", progress = "Habt Ihr die Befehle gefunden?", completion = "Die Bansheekönigin ist anders als die vorherigen Kriegshäuptlinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[49746] = { id = 49746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löscharbeiten", description = "Die Horde hat meine Stadt in Brand gesetzt, {class}. Dafür wird sie bezahlen.\n\nDas Sturmsangtal ist die Kornkammer von Kul Tiras, und unsere Leute brauchen Brot. Zuerst müssen wir Schadensbegrenzung betreiben.\n\nNehmt Euch ein paar Eimer und helft beim Löschen der Feuer!", sourceObjective = "Benutzt den Wassereimer, um 15 Feuer in den Ruinen von Brennadam zu löschen.", progress = "Meine Stadt brennt noch immer, {class}!", completion = "Egal ob Bomben, Feuer oder die Horde. Unsere Stadt wird nicht untergehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[49753] = { id = 49753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arsenalbau" }
quests[49754] = { id = 49754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht \"Nur Zul\"", description = "Unsere Feinde hier folg'n entweder dem Namen Zul oder sie woll'n ihn benutz'n, um Zandalar einzunehm'n.\n\nEr mit seinem Ego lässt beides zu.\n\nSie meinen, nur Zul könnt uns führ'n.\n\nÜberzeugt sie vom Gegenteil.", sourceObjective = "Beseitigt Zuls Streitkräfte.", completion = "Gut gemacht, {name}. Wenn das der tatsächlichen Bedrohung doch nur 'nen größ'ren Rückschlag versetzt hätt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49755] = { id = 49755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Artillerie", description = "Schlechte Neuigkeiten, <mein Guter/meine Liebe>. Die fahren jetzt mit ordentlicher Feuerkraft auf.\n\nWir haben einen Panzer auf dem nördlichen Hügel an der Windmühle entdeckt. Von da aus können sie die andere Seite der Stadt erreichen. Wir dürfen nicht zulassen, dass sie ihn einsatzbereit machen.\n\nWas haltet Ihr davon, sie ihre eigene Medizin schmecken zu lassen? Wenn Ihr den Kommandanten ausschalten könnt, habt Ihr einen brandneuen Panzer ganz für Euch allein. Stellt Euch mal vor, was Ihr damit bei denen anrichten könntet!", sourceObjective = "Tötet Kommandant Wermut und übernehmt die experimentelle Kriegsmaschine.", completion = "Das hat ganz schön gekracht! Ich bin nur froh, dass es die Horde getroffen hat und nicht uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[49756] = { id = 49756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Mächte", description = "Die Alten Götter haben einen ihrer Gesichtslosen nach Donnerfels geschickt. Dieses Ungeheuer entweiht die Stadt meines Volkes!\n\nWir müssen sie gemeinsam von diesem Abschaum befreien.\n\nIch bin überzeugt, dass wir mit der Vernichtung dieses Herolds unsere Feinde aus Mulgore vertreiben werden. Mögen unsere Waffen unter unseren Feinden wüten, {name}!", sourceObjective = "Bezwingt Qy'telek, den Herold von Uul'gyneth.", progress = "Dieser Herold der Alten Götter muss aufgehalten werden.", completion = "Gute Arbeit, {name}. Meine Leute werden ab hier übernehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49757] = { id = 49757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Katze auf dem heißen Kupferdach", description = "Meine Eltern haben gesagt, dass wir von hier fortmüssen, aber ich will Kratzi nicht zurücklassen!\n\nSie ist so sanft und lieb und weich und knuffig! Sie muss sich da droben auf dem Balkon ganz doll fürchten!\n\nBitte helft ihr!", sourceObjective = "Klettert an dem brennenden Haus hoch und rettet Kratzi.", progress = "Wir können Kratzi nicht hierlassen!", completion = "Juchhu!\n\nIst sie nicht die liebste und perfekteste Miezekatze von allen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[49758] = { id = 49758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sendet das Signal!", description = "Meine Leute sin' keine Anhänger von Zul. Wir ham geseh'n, zu was er fähig is'.\n\nWeit draußen im Haf'n ham sich Zuls Verräter mit den Mogu verbündet, um meine Schiffe zu kapern! Verlier'n wir die Flotte un' den Haf'n, verlier'n wir die Stadt!\n\nWir müss'n das Volk von Zuldazar wiss'n lass'n, dass wir nicht aufgeb'n. Wir hol'n uns die Schiffe zurück und verjag'n die Verbrecher. \n\nIhr müsst die Türme mit der loagesegneten Flamme erleuchten. Sie war stets 'n Zeichen dafür, dass die Bucht der Könige zu Zandalar gehört!", sourceObjective = "Begebt Euch zum Schiff.", completion = "Ihr seid gerade rechtzeitig gekomm'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[49759] = { id = 49759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkstattbau" }
quests[49766] = { id = 49766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der nächste Schritt", description = "Wir haben darüber nachgedacht, wie man die Zandalari am besten für unsere Sache gewinnen könnte.\n\nDie Prinzessin ist auf dem Weg nach Nazmir, um die Bluttrolle zu bekämpfen. Ihre Meinung hat großes Gewicht beim Rat und bei ihrem Vater.\n\nGeneral Jakra'zet verabscheut die Horde. Wenn wir ihn aus dem Rat der Zanchuli entfernen könnten, würde dies unsere Chancen enorm erhöhen.\n\nWir sollten auch weiterhin versuchen, den König von Zuldazar auf unsere Seite zu bringen. Die Stadt ist groß und birgt viele Geheimnisse.", sourceObjective = "Wählt Euren nächsten Schritt in Zandalar.", sourceObjectiveStatus = "unverified-source-field" }
quests[49767] = { id = 49767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der nächste Schritt", description = "Wir haben darüber nachgedacht, wie man die Zandalari am besten für unsere Sache gewinnen könnte.\n\nDie Prinzessin ist auf dem Weg nach Nazmir, um die Bluttrolle zu bekämpfen. Ihre Meinung hat großes Gewicht beim Rat und bei ihrem Vater.\n\nGeneral Jakra'zet verabscheut die Horde. Wenn wir ihn aus dem Rat der Zanchuli entfernen könnten, würde dies unsere Chancen enorm erhöhen.\n\nWir sollten auch weiterhin versuchen, den König von Zuldazar auf unsere Seite zu bringen. Die Stadt ist groß und birgt viele Geheimnisse.", sourceObjective = "Wählt Euren nächsten Schritt in Zandalar.", sourceObjectiveStatus = "unverified-source-field" }
quests[49768] = { id = 49768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwarys Posten", description = "Der größte Jäger Eurer Lande, der Zwerg Nesingwary, is' gekomm', um an der großen Jagd teilzunehm'n.\n\nWenn Ihr Euch traut, ihn zu begleit'n, reist zu Nesingwarys Posten im nordöstlich'n Bereich von Zuldazar.", sourceObjective = "Sprecht mit Hemet Nesingwary an Nesingwarys Posten.", completion = "Willkommen zur Jagd.", sourceObjectiveStatus = "unverified-source-field" }
quests[49769] = { id = 49769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörung des Kataklysmus", description = "In den letzten Jahren ist einer der größten Loatempel der Zandalari aus mysteriösen Gründen ins Meer gestürzt. Es wird immer noch darüber spekuliert, warum das passiert ist und welche Schätze bei der Katastrophe mit in die Tiefe gerissen wurden.\n\nMein Cousin Rokor kümmerte sich um die Bergungsaktion. Innerhalb des Tempels gab es viele mächtige Gegenstände, die Wissen und Macht bieten. Ich bin sicher, er wird jemanden wie Euch mit starken Armen und heilen Knien brauchen.", sourceObjective = "Findet Rokor am Strand der Plünderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[49772] = { id = 49772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Allianz", description = "Die Armee des Lichts hatte bei ihrer Gründung nur ein Bestreben: die Legion zu besiegen. Dieses Ziel haben wir erreicht, aber nun wird uns eine neue Pflicht auferlegt.\n\nAzeroth wird von allen Seiten angegriffen. Nutzt die Fähigkeiten, die Ihr gelernt habt, um gegen die Dunkelheit zu kämpfen und die Ideale der Allianz zu bewahren.\n\nReist nach Sturmwind. Sucht in der Botschaft den Botschafter des Königs auf und zieht dann aus, das Licht zu verbreiten.\n\nPheta thones gamera, {name}.", sourceObjective = "Trefft Euch mit Botschafter Moorgard in der Botschaft von Sturmwind.", completion = "Was haben wir denn hier? Einer der berühmten Lichtgeschmiedeten Draenei! Willkommen, willkommen.\n\nIch danke Euch für Eure Dienste im Kampf gegen die Legion, {name}. Ihr seid wahrlich eine Inspiration.", sourceObjectiveStatus = "unverified-source-field" }
quests[49773] = { id = 49773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Horde", description = "Für die Hochbergtauren bricht eine neue Ära an, {name}.\n\nNach Jahrhunderten der Trennung wurden wir mit unseren Geschwistern in Kalimdor wiedervereint. Und im Kampf um unser Land fanden wir in den Völkern der Horde neue Verbündete.\n\nUm unseren Mitstreitern zu zeigen, welche Stärke unser Pakt bringt, müssen mutige Tauren wie Ihr dem Ruf des Abenteuers folgen.\n\nIhr wurdet nach Orgrimmar eingeladen. Trefft Euch mit dem Botschafter in der Botschaft des Kriegshäuptlings und beginnt dann Eure Reise durch Azeroth.\n\nMöge die Erdenmutter mit Euch sein, {name}.", sourceObjective = "Trefft Euch mit Botschafter Schwarzwacht in der Botschaft von Orgrimmar.", completion = "Seid Ihr der Neue? Dann soll ich Euch willkommen heißen. Hier, nehmt diesen Brief.\n\n<Schwarzwacht seufzt entnervt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49774] = { id = 49774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blatt in den Mund nehmen", description = "Ich hab früher vielleicht 'n paar fiese Sachen gemacht, aber ich lass die Wache hier nich' einfach sterb'n.\n\nZulajin hat kräftig in Zaluto reingebiss'n... un' ihm dabei 'ne Portion fiesen Voodoo verpasst.\n\nAber keine Sorge, denn heute is' unser Glückstag. Ich hab 'ne Idee, wie wir ihn heil'n könn'. In der Nähe wachs'n nämlich Süßblattbüsche!\n\nDie Blätter von den Büschen sin' für ihre Heilfähigkeiten bekannt. Holt mir 'n paar davon, dann kann ich dies'n Zaluto vielleicht rett'n.\n\nDas is' die einzige Chance, die wir ham!", sourceObjective = "Sammelt 8 Süßblätter.", progress = "Habt Ihr die Süßblätter?", completion = "Ihr habt die Süßblätter! Un' wohl auch noch genug davon!", sourceObjectiveStatus = "unverified-source-field" }
quests[49775] = { id = 49775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel zur Brigg", description = "Wenn man was über 'n Troll lern' will, muss man nur beobacht'n, wie er reagiert, sobald er die Wahrheit über Zul erfährt.\n\nDiese Garza is' 'ne nichtsnutzige, hinterlistige, Schiffe stehlende Verräterin. Es sind Fanatiker wie sie, die diesem Ketzer freiwillig in den Schlund von 'nem Alten Gott folg'n.\n\nIch bin eher von der Sorte, die ihr die Hauer rausreißen und sie damit verprügeln will.\n\nIch hoff darauf, dass Ihr ihr den Schlüssel abnehmt und unsre Wellenbezwingerin un' die Mannschaft befreit!", sourceObjective = "Besorgt den Schlüssel von Rüstmeisterin Garza.", progress = "Habt Ihr ihr den Schlüssel abgenomm'n?", completion = "Garza war schon lange verlor'n. Maset is' wohl so streitlustig wie immer. Wir werd'n raus zu den Schiffen aufbrech'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[49776] = { id = 49776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teer ist die Lösung", description = "Ich will nich' lüg'n... Ich hab in meiner Jugend fiese Sachen gemacht un' muss seitdem mit der Schande leb'n.\n\nAber ohne meine Heilkünste wird Zaluto hier sterb'n. Un' wir werd'n alle sterb'n, wenn sich keiner um den Dinosaurier kümmert.\n\nIn dieser Gegend gibt's jede Menge Teer. Den brauch ich, um Zaluto von seiner Infektion zu heil'n.\n\nHolt mir den Teer, dann kann ich Zaluto vielleicht vor diesem Schicksal bewahr'n.", sourceObjective = "Sammelt 6 Brocken klebrigen Teers.", progress = "Wir brauch'n jede Menge klebrigen Teer!", completion = "Gut gemacht! Das is' genau das Zeugs, das wir brauch'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[49777] = { id = 49777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Flucht", description = "<Der Wachhauptmann scheint tödlich verwundet zu sein.>\n\nWir ham Gefangene transportiert, als wir plötzlich angegriffen wurd'n... ein riesiger Teufelssaurier... hat alles niedergemetzelt.\n\nDie meisten der Gefangenen sin' dem Blutbad entkomm'... Das sin' Schwerverbrecher. Man kann sie nich' einfach frei rumlauf'n lass'n!\n\nIch hab 'nen Blutschwur geleistet, sie nach Vol'dun zu bring'n... Ich werd wahrscheinlich hier sterb'n, aber ich werd nich' als Schwurbrecher sterb'n!\n\nFindet die entkommenen Kriminellen un' bringt sie nach Vol'dun...", sourceObjective = "Eskortiert die entflohenen Gefangenen ins Exil.", progress = "Habt Ihr die entfloh'nen Gefangenen gefund'n?", completion = "Ich danke Euch... Wenn ich hier sterb, hab ich zumindest mein'n Schwur erfüllt, bevor ich meine Vorfahren wiederseh.", sourceObjectiveStatus = "unverified-source-field" }
quests[49778] = { id = 49778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht nicht ins Licht", description = "Also, das is' der Augenblick der Wahrheit! Jetzt werd'n wir seh'n, ob mein Voodoo Zaluto rett'n kann.\n\nIch hätt's Euch ehrlich sag'n soll'n, dass das vielleicht nich' funktioniert. Voodoo is' ja nich' gerade 'ne exakte Wissenschaft.\n\nIhr müsst Zaluto festhalt'n, denn das wird wehtun. Fürchterlich wehtun.", sourceObjective = "Haltet Zaluto fest, während Jin'Tiki ihn heilt.", completion = "Zaluto is' dem Tod entkomm'n, aber is' noch schwach. Wir ham noch mehr zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[49779] = { id = 49779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch und durch böse", description = "Ich geh hier nich' weg, bevor Zulajin nich' tot is', sonst fällt der über die nächste Karawane her, die hier vorbeikommt.\n\nIch hab 'nen Plan, aber wir müss'n zusammenarbeit'n, wenn das klapp'n soll.\n\nHier in der Gegend gibt's laufende Raptor'nskelette. Ich weiß nich', was für 'n Voodoo die hergezaubert hat, aber die müss'n weg.\n\nDamit mein Plan funktioniert un' wir Zulajin töt'n könn', brauch'n wir so viel Platz wie möglich.", sourceObjective = "Tötet 10 Knochenraptoren.", completion = "Gut, dass Ihr diese Knochenraptor'n erledigt habt. Auch wenn das nur 'ne Straße für Kriminelle ist, hab'n die's zumindest verdient, lebendig in Vol'dun anzukomm'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49780] = { id = 49780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergung uralten Feuers", description = "Zaluto hat 'n irren Plan, wie wir Zulajin töt'n könn'. Hätt nich' gedacht, dass 'ne Wache sich so was Schlaues ausdenk'n könnte.\n\nHier gibt's überall uraltes Mojo... Keine Ahnung, was das mal war, aber damit könn' wir bestimmt was anfang'n.\n\nIn den Statuen in den Teergrub'n brennt immer noch Feuermojo. Das brauch'n wir, um Zulajin zu töt'n.\n\nNehmt mein' Fetisch un' zieht damit den Rest von dem Feuer aus'n Statuen raus.\n\nAber kommt mit dem Feuer nich' zu nah an den Teer!", sourceObjective = "Absorbiert Feuermojo aus 4 Statuen der Nazmani.", completion = "Der Fetisch is' voller Feuermagie! Gut, die braucht Ihr nämlich für den nächst'n Schritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49781] = { id = 49781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt mich doch", description = "Also gut, jetz' is' die Zeit für Euch gekomm', gegen Zul'Ajin selbst zu kämpf'n!\n\nJin'Tikis Fetisch is' jetz' voll mit dem uralten Feuer. Ihr werdet auf meinem Raptor hier reit'n un' Zul'Ajin in die Teergruben lock'n.\n\nUn' dann... werdet Ihr die Teergruben mit dem Fetisch anzünd'n! Das sollte Zul'Ajin den Rest geb'n.\n\nUn' wenn nich', müsst Ihr eben improvisier'n. Viel Glück!", sourceObjective = "Reitet auf Zalutos Raptor, um Zulajin in die Teergruben zu locken, und setzt sie dann in Brand.", completion = "Ich wusste, dass Ihr das mit Zulajin hinbekommt, kein Problem! Ich glaub, für mich wird's Zeit, dem Dschungel ein für alle Mal Lebwohl zu sag'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[49782] = { id = 49782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition der Lichtgeschmiedeten", sourceObjective = "Trefft Hauptmann Fareeya an Bord der Vindikaar.", completion = "Pflicht. Ehre. Opfer. Die Lichtgeschmiedeten streben danach, diese Werte zu verkörpern und Ihr seid ein strahlendes Beispiel dafür.\n\nEs ist mir eine Ehre, Euch mit einem Symbol Eurer Einsatzbereitschaft auszuzeichnen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49783] = { id = 49783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition des Hochbergs", sourceObjective = "Trefft Mayla Hochberg in Donnertotem.", completion = "Ihr habt unseren Stämmen viel Ehre gemacht, {name}. Es ist nur angebracht, Euch ein Symbol unserer Wertschätzung zu überreichen.\n\nDer Hochberg bleibt stark... denn Ihr habt den Mut, für ihn zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49784] = { id = 49784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition der Nachtgeborenen", description = "Ihr gehört zu den ersten Shal'dorei, die sich heraus in die weite Welt gewagt und die Wildnis von Azeroth erkundet haben. Doch nun ist es Zeit, heimzukehren.\n\nBegebt Euch nach Suramar. Ihr habt unserem Volk geholfen, seinen Platz in dieser Welt zu finden. Dafür möchten wir Euch danken.", sourceObjective = "Trefft Euch mit der Ersten Arkanistin Thalyssra bei der Nachtfestung.", completion = "Als wir von den Fesseln der Legion befreit wurden, glaubten einige unter den Shal'dorei, dass wir weiter abgeschottet leben sollten. Allein.\n\nWas Ihr in Azeroth zustande gebracht habt, hat uns gezeigt, dass es die richtige Entscheidung war, wieder unseren Platz in dieser Welt zu beanspruchen. Es ist mir eine Freude, Euch dieses Symbol der Dankbarkeit Suramars zu überreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49785] = { id = 49785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtung der Waffe", description = "Ich hab mir die nächste Insel schon angeseh'n. Die Rezans Klaue hat 'ne mächtige Waffe an Bord.\n\nKeine Ahnung, was für eine, aber auf dem Schiff glaub'n alle, dass sie die Verteidigung unseres Heims durchbrech'n kann.\n\nGeht aufs Schiff. Vernichtet die Waffe, bevor sie gegen Zuldazar gerichtet werd'n kann!", sourceObjective = "Untersucht die Waffe.", completion = "Damit hab ich nich' gerechnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[49787] = { id = 49787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geisterlande", description = "Wisst Ihr, wie die Leerenelfen der Allianz beigetreten sind?\n\nEines Tages erfuhr Alleria Windläufer von einem Blutelfen namens Umbric.\n\nEr und seine Gefolgsleute wurden für ihr Studium der Leerenmagie aus Silbermond verbannt.\n\nAlleria glaubte, sie könne Umbric und seine Anhänger überzeugen, sich der Allianz anzuschließen und verhindern, dass die Leere sie verderbt.\n\nAlles begann, als sie ein Portal in die Geisterlande öffnere...", sourceObjective = "Macht Umbrics Zuhause in den Geisterlanden ausfindig.", progress = "Diese Lande wecken Erinnerungen. Sowohl gute als auch schlechte.", completion = "Umbrics Methoden sind etwas fahrlässig, aber er scheint kompetent. Wir müssen zu ihm gelangen, bevor die Situation zu gefährlich wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[49788] = { id = 49788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Allianz", sourceObjective = "Trefft Euch mit Botschafter Moorgard in der Botschaft von Sturmwind.", completion = "Ah, da seid Ihr ja, {name}! Wir haben Euch betrach– äh, erwartet!", sourceObjectiveStatus = "unverified-source-field" }
quests[49789] = { id = 49789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gelöbnis", description = "Die Astralen lauerten geduldig auf jemanden, der sich weit genug in das Studium der Leere vertieft hatte, um vom Einfluss der Alten Götter verderbt zu werden.\n\nWir sind rechtzeitig eingetroffen, um einzuschreiten, und ich werde sie lehren, dem Flüstern zu widerstehen.\n\nUmbric ist bereit, sich der Allianz anzuschließen. Kehren wir nach Sturmwind zurück und informieren wir König Wrynn.", sourceObjective = "Kehrt nach Sturmwind zurück und sprecht mit Anduin.", sourceObjectiveStatus = "unverified-source-field" }
quests[49791] = { id = 49791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren, aber nicht vergessen", description = "Ich weiß nicht, welcher Wahnsinn von meinen Leuten Besitz ergriffen hat, aber wir müssen dem Irrsinn gemeinsam ein Ende bereiten.\n\nNehmt diese Glocke. Sie ruft die Seelen der kürzlich Verstorbenen und kann sie später wieder freigeben. Wir in Sturmsang begraben unsere Toten nicht. Die Gezeiten holen sich alles.\n\nWenn sie nicht auf die Vernunft hören wollen, dann müssen wir ihnen den ewigen Frieden schenken. So oder so, sie gehören immer noch zu Sturmsang.", sourceObjective = "Sammelt 12 Seelen mit der Totenglocke ein.", progress = "Es ist eine makabre Aufgabe, doch es ist eine Bürde, die wir tragen müssen.", completion = "Es ist vollbracht. Wir werden sie an einem friedlicheren Ort wieder freilassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49792] = { id = 49792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebunden und unterdrückt", description = "Wir hatten unseren Auftrag: Schiffe, und zwar eine Menge. Ich habe meine Jungs nach bestem Wissen angeführt.\n\nAls diese Gezeitenweisen dann auftauchten, hat sich alles geändert. Wir dachten, dass sie nur unsere Fortschritte beobachten, aber diese Bastarde haben uns angegriffen!\n\nDiese Anker halten uns hier fest und zwingen uns dazu, bis zum Umfallen zu arbeiten. Niemand hat so ein Schicksal verdient... Ihr müsst meine Jungs retten!", sourceObjective = "Zerstört 8 Anker der Bindung.", completion = "Ich schulde Euch was, Fremdling!", sourceObjectiveStatus = "unverified-source-field" }
quests[49793] = { id = 49793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittel zum Zweck", description = "Vor lauter Eile habe ich ganz vergessen, mein rituelles Werkzeug mitzubringen. Wir Gezeitenweisen steigern damit unsere Macht, wisst Ihr?\n\nEhrlich gesagt hatte ich auch gar nicht damit gerechnet, dass ich es auf einer eigentlich friedlichen Reise brauchen könnte.\n\nAnderson wird sein Werkzeug auch nicht dabeihaben. Ich bin mir sicher, dass ihm die Miliz, die ihn aus seinem Haus abgeführt hat, keine Chance gelassen hat, zu reagieren.\n\nSein Werkzeug sollte also noch irgendwo auf dem Werftgelände sein. Wir müssen es finden, sonst werde ich Euch keine große Hilfe sein.", sourceObjective = "Holt Euch Bruder Andersons Gezeitenkris, sein abgründiges Leuchtfeuer und einen Mantel des Wellenrufers.", progress = "Wir müssen einen vollständigen Satz rituellen Werkzeugs finden. Ich fürchte, wir werden es brauchen.", completion = "Diese Initianden sind nicht mal annähernd bereit, unser heiliges Werkzeug zu führen. In unseren Händen ist es deutlich besser aufgehoben.", sourceObjectiveStatus = "unverified-source-field" }
quests[49794] = { id = 49794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stürmische Gezeiten", description = "Diese Triebfeder wurde nicht von einem Ingenieur angepasst. Die Runen auf der Oberfläche können nur von einem Gezeitenweisen stammen.\n\nIhre Meeresmagie ist unverwechselbar. Ich wette, dass derjenige, der dies getan hat, auch für den Tod von Anderson verantwortlich ist.\n\nIch weiß nicht, wer es ist, aber er ist bestimmt noch in der Nähe. Haltet die Augen offen, dann werdet Ihr denjenigen... oder diejenige... schon finden.", sourceObjective = "Zieht Schwester Ava zur Rechenschaft.", completion = "Das verheißt nichts Gutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[49800] = { id = 49800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Spinnen!" }
quests[49801] = { id = 49801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Paarungsstrategie", description = "Aggression ist gut. Ich stimme Jangalar zu, dass Ben'jin sich weniger passiv verhalten muss, wenn das alles funktionieren soll. Ich werde beweisen, dass die Wissenschaft der beste Weg ist, indem ich eine Injektion für ihn herstelle.\n\nDie Alchemie lehrt uns, dass bei dieser Gattung ein Stoff aus der Gallenblase für die Aggression zuständig ist. Die Klingenschwingen in dieser Gegend greifen ständig an, sie haben mehr als genug Aggression für unsere Zwecke.\n\nSammelt einige ihrer Gallenblasen, dann mische ich eine Kur, die unseren Großen im Nu wieder in Schwung bringt.", sourceObjective = "Sammelt 8 Gallenblasen von invasiven Klingenschwingen.", progress = "Habt Ihr all die benötigten Gallenblasen für mich besorgt? Wissenschaft hat nicht sicher zu sein...", completion = "Das hat mir gefehlt! Was für ein Geruch!\n\nMit diesen Gallenblasen kann ich eine Aggressionsformel herstellen, die locker für einen Brutosaurus ausreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[49803] = { id = 49803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachwechsel", description = "Ich zweifle nicht daran, dass Ihr <ein/eine:c> recht <fähiger/fähige:c> {class} seid, <Festländer/Festländerin>, aber wenn wir es in einem Stück zum Kronsteiganwesen schaffen wollen, brauchen wir Hilfe. Eine kleine Gruppe wäre ideal... stark genug, um Bedrohungen des Zirkels auszuschalten, aber auch klein genug, um nicht aufzufallen.\n\n<Lesner holt ein Bündel Briefe hervor.>\n\nIch habe neue Befehle für einige meiner besten Soldaten. Sie sollen Eurem Glutorden beitreten. Sie werden Euch und Fräulein Kronsteig unterstellt sein. Bitte überreicht ihnen diese Befehle, damit sie sich auf den Einsatz vorbereiten können.", sourceObjective = "Übergebt die Rekrutierungsbefehle an Hauptmann Morgenlicht, Fähnrich Yorrick, Fähnrich Knüpp, Leutnant Hartwasser und Falkner Nottlich in Aroms Wehr.", completion = "Ich übertrage Euch nur widerwillig das Kommando über diese Soldaten, aber es muss sein.\n\nIch hoffe, Ihr werdet sie gut führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49804] = { id = 49804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharf nachgedacht", description = "Ich habe Grund zur Annahme, dass der Zirkel Aroms Wehr bereits infiltriert hat. Unter den Flüchtlingen aus Korlach gibt es viele unbekannte Gesichter und wir wissen, dass sie Magie nutzen können, um wie wir auszusehen.\n\nDiese Nadel wurde aus reinem Silber gefertigt. Wenn die Hexen wirklich empfindlich auf Silber reagieren, dann könnte ein Stich hiermit ausreichen, um ihren Zauber zu brechen.\n\nEs wird den Flüchtlingen bestimmt nicht gefallen, gepikt zu werden, aber sie müssen verstehen, dass es zum Wohl der Stadt geschieht... und womöglich sogar zum Wohl von ganz Drustvar.", sourceObjective = "Setzt Luzillas Nähnadel bei 10 Flüchtlingen aus Korlach ein, um die Hexen in Aroms Wehr zu enttarnen.", completion = "Es hat funktioniert?! Ich wusste, dass wir auf der richtigen Fährte sind!\n\nSchade, dass wir kein ganzes Arsenal an Silberwaffen herumliegen haben, aber ich glaube, ich weiß, wie wir das lösen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[49805] = { id = 49805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instrumente böser Absichten", description = "<Offenbar hat irgendeine leichtsinnige Hexe versucht, diesen Zauberfolianten zu verstecken... und das ziemlich schlecht. Wenn ein argloser Dorfbewohner Besitztümer des Zirkels finden sollte, könnte das schlimm für ihn enden.\n\nEs wäre wohl eine gute Idee, wenn Ihr alle Besitztümer des Zirkels zerstört, die Ihr in Aroms Wehr findet.>", sourceObjective = "Zerstört 12 Herzbannobjekte in Aroms Wehr.", completion = "Das Entsorgen der Besitztümer dieser Hexen war eine gute Idee.\n\nNicht auszudenken, was passiert wäre, wenn ein unschuldiger Dorfbewohner mit diesen Dingen herumgespielt hätte!", sourceObjectiveStatus = "unverified-source-field" }
quests[49806] = { id = 49806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Machenschaften", description = "<Im Besitz der Hexe befand sich unter anderem eine primitiv gezeichnete Karte von Aroms Wehr.\n\nEin Symbol markiert eine Stelle, die der Eingang zu einem Keller unterhalb eines der Gebäude zu sein scheint.\n\nWenn dieser Ort für den Zirkel wichtig ist, lohnt es sich vielleicht, ihn auszuspähen.>", sourceObjective = "Erkundet den Ort, der auf der primitiven Karte markiert ist.", progress = "Was ist das? Eine Karte?", completion = "Ihr habt ihre Anführerin gefunden? Hervorragende Arbeit, {class}!\n\nJetzt, da Ihr die Machenschaften des Zirkels hier vollständig durchkreuzt habt, werden die Bürger von Aroms Wehr wieder sicher sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[49807] = { id = 49807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Orden", description = "Bevor wir gehen, habe ich noch eine Bitte an Euch.\n\nWährend Ihr unsere Inquisitoren rekrutiert und den Zirkel aus Aroms Wehr vertrieben habt, war ich so frei, beim örtlichen Schneider eine Bestellung aufzugeben.\n\nIch ließ ihn anhand der Zeichnungen im Folianten einige Uniformen schneidern, die denen des alten Ordens nachempfunden sind.\n\nDa Ihr unsere Inquisitoren anführen werdet, halte ich es für angebracht, dass Ihr ihnen ihre neuen Ornate präsentiert.", sourceObjective = "Verteilt das Ornat des Inquisitors an die Rekruten in Aroms Wehr.", progress = "Ihr sollt sie in den Orden einführen, nicht mich!", completion = "Sieh einer an, richtig schick und offiziell.\n\nUnd nun, denke ich, wird es Zeit, dass wir uns den Herzbannzirkel vorknöpfen. Ich glaube, der Marschall hat einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[49809] = { id = 49809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Aus den Schatten" }
quests[49810] = { id = 49810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kolossale Kuppelei", description = "Wir ham da ein Problem, es geht um die Liebe un' Ihr kommt gerade rechtzeitig.\n\nDie weißen Brutosaurier, das Männchen Ben'jin und das Weibchen Maka'fon sin' die letzten ihrer Art. Alle anderen sin' nich' mehr.\n\nDie Liebe scheint sie nich' zu interessier'n. Würdet Ihr mir un' meiner neuen Freundin Kala helf'n, ihnen eine letzte Chance auf 'ne Zukunft zu biet'n?\n\nPlatziert mein Voodoototem in ihrer Nähe, damit ich ihre Gefühle spür'n kann. So kann ich hoffentlich 'nen Weg finden, ihnen zu helf'n.", sourceObjective = "Platziert das Voodoototem von Hexendoktorin Jangalar in der Nähe beider Brutosaurier.", progress = "Platziert das Voodoototem in der Nähe von beiden Brutosauriern, dann kann ich ihre Gefühle spür'n.", completion = "Wir müss'n Ben'jin zu neuer Anziehungskraft verhelf'n un' Maka'fon in Stimmung bring'n. Was wird uns da besser voranbring'n? Voodoo oder Wissenschaft?", sourceObjectiveStatus = "unverified-source-field" }
quests[49812] = { id = 49812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delas in Dalaran", description = "Delas Mondfang braucht unsere Hilfe. Im Gegenzug wird sie uns bei der Entschlüsselung des Kodex der Befehlsgewalt helfen.\n\nIch beschwöre Euch, sie so schnell wie möglich aufzusuchen. Man findet sie häufig am Denkmal für den großen gefallenen Anführer der Kirin Tor, Antonidas.", sourceObjective = "Findet Delas Mondfang an Antonidas' Denkmal in Dalaran.", completion = "Der Göttin sei Dank, dass Ihr da seid, {name}. Ich hoffe, dass Ihr mir helfen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49813] = { id = 49813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Abenteuer ruft", description = "Die Kunde Eurer Heldentaten hat sich in ganz Azeroth herumgesprochen... und selbst darüber hinaus. Eure Fertigkeiten werden an anderer Stelle benötigt.\n\nWäret Ihr bereit, durch das Dunkle Portal zu reisen und die Legion in den zerrütteten Landschaften der Scherbenwelt zu bekämpfen?\n\nOder wollt Ihr nach Norden fliegen und Euch in Nordend dem Kampf gegen den Lichkönig anschließen?\n\nIhr habt die Wahl, <Abenteurer/Abenteurerin>.", sourceObjective = "Verwendet die Spezialaufträge, um den Zielort Eures nächsten Abenteuers festzulegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49814] = { id = 49814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die richtige Stimmung", description = "Wenn's um Liebe geht, ist Stimmung alles, und Maka'fon is' wohl nich' in Stimmung.\n\nDas Voodooräucherwerk von 'ner erfahr'nen Hexendoktorin wie mir selbst würd' sicher die Flamme des Muttergeistes in ihrem Herzen entfach'n.\n\nDafür eignen sich am besten Duftbinsen, die wir im Dschungel find'n.\n\nDie Binsen der Zandalari wachs'n in der Nähe des Wassers. Sammelt 'ne ordentliche Menge, dann fertige ich 'n Räucherwerkbündel, das für Stimmung sorgt.", sourceObjective = "Findet 7 Duftbinsen, um Räucherwerk für Maka'fon die Reizbare herzustellen.", progress = "Sucht in der Nähe vom lebensspendenden Wasser nach Binsen, aus denen ich mit meinem Voodoo Räucherwerk für die Brutosaurier mach'n kann.", completion = "Gut gemacht! Ich werd die Binsen zu Räucherwerkbündeln web'n un' meine besten Zauber darauf wirk'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49816] = { id = 49816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: To Outland!", description = "Die Brennende Legion – eine riesige Armee aus unzähligen Dämonen – hat die Scherbenwelt, die verwüstete Heimat der Orcs, angegriffen. Es werden Abenteurer der Horde gesucht, um die Reste der Scherbenwelt vor der vollständigen Auslöschung durch diese Dämoneninvasion zu bewahren.\n\nReist in die Verwüsteten Lande und durchquert das Dunkle Portal.", sourceObjective = "Begebt Euch durch das Dunkle Portal in die Verwüsteten Lande.\n\nDer Magier von Thrallmar in der Portalkammer von Orgrimmar kann Euch helfen, dorthin zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49817] = { id = 49817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Nordend!", description = "Im Norden rührt sich der Lichkönig.\n\nEine Armee der Untoten marschiert auf seinen Befehl durch Nordend und verbreitet überall auf ihrem Weg die grauenhafte Seuche.\n\nIhr müsst sie aufhalten, {name}.", sourceObjective = "Reist mit dem Zeppelin nach Nordend.\n\nIhr könnt in Tirisfal den Zeppelin zum Heulenden Fjord oder in Orgrimmar den Zeppelin in die Boreanische Tundra nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49818] = { id = 49818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Fort Daelin", description = "Ich wurde von meinem Befehlshabenden nach Brennadam geschickt, um einen Gezeitenweisen zu finden, der uns bei Fort Daelin im Westen helfen kann. Die Naga haben einen neuen Angriff auf die Bastion gestartet, und es ist der größte, den wir jemals gesehen haben. \n\nLeutnant Bauer ist dabei, den Zivilisten im Dorf in der Nähe des Forts zu helfen. Sie kann jede Hilfe brauchen, die sie kriegen kann.", sourceObjective = "Meldet Euch bei Leutnant Bauer in Seebrise.", completion = "Diese Fischersleute lassen sich nicht so einfach rumschubsen. Also sollten sie hier mit ein wenig Hilfe allein zurechtkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49831] = { id = 49831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Tiefen", description = "Wir müssen uns auf einen Angriff vorbereiten.\n\nBemannt die Kanonen!\n\nVerteidigt den Damm um jeden Preis!", sourceObjective = "Verteidigt den Damm gegen Azsharas Angriffe.", completion = "Wir haben es geschafft! Die Naga sind besiegt, und der Damm ist noch intakt!", sourceObjectiveStatus = "unverified-source-field" }
quests[49832] = { id = 49832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unlesbare Schriftrolle", description = "<In dem wasserdichten Behälter liegt eine unlesbare Schriftrolle unbestimmbaren Alters und unbekannter Herkunft.\n\nVielleicht können die Tortollaner an der Küste ja entziffern, was auf dem Pergament geschrieben steht?>", sourceObjective = "Bringt die Schriftrolle zu den Tortollanern an der Windgepeitschten Küste.", completion = "Was habt Ihr gefunden, Reisender? Aha, eine in geheimnisvoller Schrift verfasste Schriftrolle. Ein sehr interessanter Fund!\n\n<Nola nimmt die Schriftrolle sorgfältig in Augenschein.>\n\nIch habe solche Schriftzeichen zwar noch nie zuvor gesehen, aber vielleicht weiß Kugro ja mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[49846] = { id = 49846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg an zwei Fronten", description = "{name}! Wieder einmal wurdet Ihr gerufen, um der Horde bei höchst dringlichen Angelegenheiten zu helfen.\n\nSeid Ihr bereit, die Horde in ihrem Kampf gegen Todesschwinge und den Schattenhammer zu unterstützen?\n\nOder wollt Ihr lieber in den Süden nach Pandaria fliegen und dessen Ressourcen für uns sichern, bevor es die Allianz tut?\n\nTrefft Eure Wahl und werft Euch in die Schlacht!", sourceObjective = "Verwendet die Spezialaufträge, um den Zielort Eures nächsten Abenteuers festzulegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49851] = { id = 49851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katastrophenersthelfer", description = "Todesschwinge, der Drachenaspekt des Todes, hat seine Diener entsandt, um alles Leben auf Azeroth auszulöschen.\n\nScharfseher Krogar in Orgrimmar kann Euch mehr über den Hyjal, Vashj'ir und die anderen Gebiete, auf die es Todesschwinge abgesehen hat, erzählen.", sourceObjective = "Meldet Euch bei Scharfseher Krogar in Orgrimmar.", completion = "Ah, {name}. Danke, dass Ihr meinem Aufruf gefolgt seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[49852] = { id = 49852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Pandaria!", description = "Ihr werdet hiermit aufgefordert, Euch unverzüglich in der Feste Grommash zu melden.\n\nWir haben von einem neuen, ressourcenreichen Kontinent im Süden erfahren und beabsichtigen, einen kleinen Trupp Soldaten dorthin zu entsenden, um ihn für die Horde zu beanspruchen.", sourceObjective = "Meldet Euch in der Feste Grommash in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[49855] = { id = 49855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod und Verderben am Hyjal", description = "Unsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nIhr könnt mit Cenarius' Abgesandtem Schwarzhuf sprechen, um Zugang zur Mondlichtung zu erlangen. Er hält sich im Taurenviertel im Tal der Weisheit in Orgrimmar auf.", sourceObjective = "Sprecht mit Cenarius' Abgesandtem Schwarzhuf, um auf die Mondlichtung zu reisen.", completion = "Wir wussten, dass die Horde Hilfe schicken würde. Und Ihr kommt keine Sekunde zu früh!", sourceObjectiveStatus = "unverified-source-field" }
quests[49860] = { id = 49860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Abenteuer ruft", description = "Die Kunde Eurer Heldentaten hat sich in ganz Azeroth herumgesprochen... und selbst darüber hinaus. Eure Fertigkeiten werden an anderer Stelle benötigt.\n\nWäret Ihr bereit, durch das Dunkle Portal zu reisen und die Legion in den zerrütteten Landschaften der Scherbenwelt zu bekämpfen?\n\nOder wollt Ihr nach Norden fliegen und Euch in Nordend dem Kampf gegen den Lichkönig anschließen?\n\nIhr habt die Wahl, <Abenteurer/Abenteurerin>.", sourceObjective = "Verwendet die Spezialaufträge, um den Zielort Eures nächsten Abenteuers festzulegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49862] = { id = 49862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: To Outland!", description = "Die Brennende Legion – eine riesige Armee aus unzähligen Dämonen – hat die Scherbenwelt, die verwüstete Heimat der Orcs, angegriffen. Es werden Abenteurer der Allianz gesucht, um die Reste der Scherbenwelt vor der vollständigen Auslöschung durch diese Dämoneninvasion zu bewahren.\n\nReist in die Verwüsteten Lande und durchquert das Dunkle Portal.", sourceObjective = "Geht durch das Dunkle Portal in den Verwüsteten Landen.\n\nDer Magier der Ehrenfeste im Magierviertel kann Euch helfen, dort hinzugelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49863] = { id = 49863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: To Northrend!", description = "Im Norden rührt sich der Lichkönig.\n\nEine Armee der Untoten marschiert auf seinen Befehl durch Nordend und verbreitet überall auf ihrem Weg die grauenhafte Seuche.\n\nIhr müsst sie aufhalten, {name}.", sourceObjective = "Reist mit einem Schiff nach Nordend.\n\nIhr könnt im Hafen von Sturmwind das Schiff in die Boreanische Tundra oder im Sumpfland das Schiff zum Heulenden Fjord nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49864] = { id = 49864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg an zwei Fronten", description = "{name}! Wieder einmal wurdet Ihr gerufen, um der Allianz bei höchst dringlichen Angelegenheiten zu helfen.\n\nSeid Ihr bereit, die Allianz in ihrem Kampf gegen Todesschwinge und den Schattenhammer zu unterstützen?\n\nOder wollt Ihr lieber in den Süden nach Pandaria fliegen und dessen Ressourcen für uns sichern, bevor es die Horde tut?\n\nTrefft Eure Wahl und werft Euch in die Schlacht!", sourceObjective = "Verwendet die Spezialaufträge, um den Zielort Eures nächsten Abenteuers festzulegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49865] = { id = 49865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm: First Responder", description = "Todesschwinge, der Drachenaspekt des Todes, hat seine Diener entsandt, um alles Leben auf Azeroth auszulöschen.\n\nNaraat der Erdsprecher kann Euch mehr über den Hyjal, Vashj'ir und die anderen Gebiete, auf die es Todesschwinge abgesehen hat, erzählen.", sourceObjective = "Meldet Euch bei Naraat dem Erdsprecher in Sturmwind.", completion = "Ah, {name}. Danke, dass Ihr meinem Aufruf gefolgt seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[49866] = { id = 49866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists of Pandaria: To Pandaria!", description = "Bitte kommt unverzüglich zur Burg Sturmwind, um Euch mit König Varian Wrynn zu besprechen.\n\nWir haben von Auseinandersetzungen in den südlichen Gewässern gehört und benötigen Eure Erfahrung als {class} bei der Untersuchung dieser Angelegenheit.", sourceObjective = "Meldet Euch bei Rell Nachtwind in Sturmwind.", completion = "Seid gegrüßt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49869] = { id = 49869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Verteidigung", description = "Die hier stationierten Soldaten geben ihr Bestes, um die Stellung zu halten, aber sie haben sehr zu kämpfen. Die Piraten haben es seit Jahren nicht gewagt, dieses Tor anzugreifen... Und sie waren bisher auch nie so zahlreich.\n\nWenn Ihr kampferprobt seid, wird Leutnant Tarenfeld Eure Bekanntschaft machen wollen. \n\nEr ist da vorne und organisiert die Miliz.", sourceObjective = "Meldet Euch bei Leutnant Tarenfeld.", completion = "Aha! Die Verstärkung!\n\nMoment mal... Wo ist der Rest Eurer Leute?", sourceObjectiveStatus = "unverified-source-field" }
quests[49870] = { id = 49870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manchmal kommt es eben doch auf die Größe an", description = "Also, die ungewollte Nebenwirkung von Ben'jins... nennen wir es 'Taschenformat'... ist, dass er jetzt die Höhle betreten kann, in der die Alphawindnatter haust!\n\nMan nennt die Bestie Düsterschweif. Wenn Ben'jin sie besiegen kann, wird er ihr Revier übernehmen und es mit lauter kleinen Brutosauriern füllen wollen, also wird er sich eine Partnerin suchen. Wenn er dann mit der empfangsbereiten Maka'fon zusammenkommt, haben alle gewonnen!\n\nLos, gebt ihm noch einen Schub von der Formel!", sourceObjective = "Verabreicht Ben'jin die \"voodooisierte\" Aggressionsformel.", progress = "Größe ist nicht alles, stimmt's? Ben'jin kann mehr Orte erreichen, wenn er klein ist... und dort kämpfen!", completion = "Das war unglaublich! Ich konnt' das Schnauben und Stampfen von hier hör'n.\n\nEinwandfrei, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49871] = { id = 49871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Flut", description = "Die Mogu wirk'n immer verzweifelter. Wahrscheinlich woll'n sie von hier verschwund'n sein, bevor sie den Zorn von dem Loa zu spür'n bekommen!\n\nDer Schoßzauberer des Kriegsfürsten hat 'ne Blockade aufgebaut un' die ham den Turm erobert.\n\nSolange Ihr Euch keinen Schlag holt, könn' Euch diese Blitzableiter gute Dienste leisten... Euch sozusagen richtig auflad'n.\n\nGeht zu Kriegsfürst Xiar und entzieht ihm seine Lebensberechtigung.\n\nLasst unsre Leute dann wiss'n, dass wir die Atem von Pa'ku zurückerobert ham!\n\nDieses Mojo hat die Macht, den Turm mit 'ner mächtig'n Explosion zu entzünd'n.", sourceObjective = "Tötet Kriegsfürst Xiar und entzündet das Signalfeuer.", completion = "Nich' übel, {name}! Unsre Arbeit is' fast getan!", sourceObjectiveStatus = "unverified-source-field" }
quests[49873] = { id = 49873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Opferschriften", description = "<Als Ihr in den Folianten blickt, erscheint ein rot aufleuchtender Vers.>\n\n\"Erst dank des Opfers wird Blut gebunden,\nDer Weg wird enthüllt und Ihr habt ihn gefunden,\nDrum sucht die Schwachen und haltet stand,\nZum Dank wird Euer Leid gebannt.\"\n\n<Als Ihr den Vers gelesen habt, bemerkt Ihr plötzlich eine Schriftrolle, die in Eurer Hand liegt.\n\nSie ist als \"Urkunde der Opferung\" beschriftet. Verschiedene Euch unbekannte Runen erscheinen auf dem Rest der Schriftrolle. Doch Ihr könnt keinen Hinweis darauf erkennen, was der Zweck dieser Schriftrolle sein könnte.>", sourceObjective = "Befragt Kronah über die Urkunde der Opferung. Folgt ihren Hinweisen, nachdem sie Euch die benötigten Informationen gegeben hat.", completion = "Wie ich sehe, habt Ihr Eure Prüfung abgeschlossen.\n\n<Kronah nimmt die Urkunde aus Eurer Hand und platziert sie auf dem Folianten. Sie verschmilzt langsam damit und verschwindet in einem blendenden Licht.>\n\nIhr habt gute Arbeit geleistet und seid nun auf alle Zeiten an den Vertrag der Opferung gebunden.\n\nJetzt sollten wir uns um wichtigere Dinge kümmern. Was haltet Ihr von Murlochirnsuppe? Ich finde sie köstlich und würde sie liebend gerne mit einem Gast teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49874] = { id = 49874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Lehrbuch", description = "Ihr öffnet das Buch und starrt erwartungsvoll auf eine leere Seite, doch nichts geschieht.\n\nInstinktiv blättert Ihr zur nächsten Seite, die ebenfalls leer ist. Vielleicht erwartet Eure Prüfung Euch weiter hinten im Buch?", sourceObjective = "Untersucht das Kompendium des Blutvergießens weiter, um mit Eurer Prüfung zu beginnen.", progress = "Ich verlasse mich darauf, dass Ihr im Kompendium des Blutvergießens sehr vorsichtig vorgeht. Wehe, ich finde wegen Eurer Waffe da Risse in den Seiten!", completion = "Gut gemacht, mein Kind. Ich erinnere mich noch an einen Gnom, der die Prüfung vor Kurzem absolvierte.\n\nIhre Geschichte war äußerst unterhaltsam zu lesen. Aber unter uns, Gnome riechen wie Haferbrei.\n\n<Kronah sieht einen Augenblick lang in Gedanken versunken in die Ferne.>\n\nAber nun seid Ihr der Träger des Vertrags des Blutvergießens und Eurem Ziel einen Schritt näher.\n\n<Kronah grinst Euch komisch an und wendet sich wieder ihren eigenen Dingen zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49875] = { id = 49875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Eindrücke", description = "Mehr kann ich Euch nicht bieten, <junger Schreiber/junge Schreiberin>. Aber Eure Reise ist noch nicht an ihrem Ende angelangt.\n\nGeht zu Eurer Ausbilderin und berichtet ihr von Eurem Erfolg.\n\n<Kronah greift nach einem seltsamen Glas.>\n\nIhr wollt vermutlich keine eingelegten Krokiliskeneier für die Reise mitnehmen, was?\n\n<Als sie das Glas öffnet, verbreitet sich der übelste Gestank, den Ihr je gerochen habt, und Ihr torkelt vor Abscheu zurück.>\n\nNa gut, dann eben nicht. Es ist ein etwas gewöhnungsbedürftiger Geschmack. Man muss seine Geschmacksnerven dafür schon ein paar tausend Jahre trainieren.", sourceObjective = "Kehrt zu Zooey Tintenritzel im Tiragardesund zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[49876] = { id = 49876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linien im Sand", description = "Mehr kann ich Euch nicht bieten, <junger Schreiber/junge Schreiberin>. Aber Eure Reise ist noch nicht an ihrem Ende angelangt.\n\nWenn Ihr nichts an Reisen auszusetzen habt und an tödlicheren Blutverträgen interessiert seid, müsst Ihr Euch nach Zandalar begeben.\n\nDort müsst Ihr in einer Gegend, die man Vol'dun nennt, einen Sethrak namens Veriss ausfindig machen.\n\n<Kronah greift nach einem seltsamen Gefäß und öffnet es. Der übelste Gestank, den Ihr je gerochen habt, steigt daraus auf und Ihr torkelt angewidert zurück.>\n\nEingelegte Krokiliskeneier mag ich am liebsten. Möchtet Ihr welche?", sourceObjective = "Begebt Euch zu Veriss bei der Terrasse der Ergebenen in Vol'dun und beginnt dort mit Euren Blutprüfungen.", completion = "Ah! Ein neuer Initiand! Woher ich das weiß? Weil Blut an Euren Händen klebt natürlich.\n\n<Auf dem Gesicht des Sethrak erscheint ein verschlagenes Grinsen.>\n\nIch bin Veriss, der örtliche Hüter der Blutverträge von Zandalar.\n\nWenn Ihr Euren Namen darin einschreiben möchtet, muss ich Euch erst um etwas bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[49877] = { id = 49877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempel von Sethraliss: Ein gebuchter Gefallen", description = "Als die Treulosen an die Macht kamen, flohen wir Ergebenen aus unserem heiligen Tempel und suchten hier Zuflucht.\n\nDoch viele von uns waren bei diesem Exodus dazu gezwungen, einige ihrer Habseligkeiten stehen und liegen zu lassen.\n\nIch selbst ließ einen Folianten zurück, aus dem man den Vertrag der Vergessenheit erlernen kann. Wenn Ihr mit den Prüfungen fortfahren möchtet, müsst Ihr mir dieses Buch holen, {name}.\n\nIch vertraue darauf, dass Ihr mich nicht enttäuschen werdet.", sourceObjective = "Bergt den Folianten der Vergessenheit aus dem Tempel von Sethraliss.", progress = "Ich gebe zu, es ist mir etwas peinlich, ihn zurückgelassen zu haben. Ein Versehen, dass ich bis heute bereue.", completion = "Ich bin erleichtert, dass Ihr ihn wiederbeschaffen konntet. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49878] = { id = 49878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schützende Schrift", description = "<Ihr öffnet das Buch, blättert es durch und seht die Porträts verschiedener Champions, die neben einer großen Bestie stehen.\n\nSchließlich erreicht Ihr einen leeren Porträtrahmen und berührt die Seite. Es erscheinen Runen in einer fremden Sprache, die sich schnell in Wörter verwandeln, die Ihr lesen könnt.>\n\n\"Ich halte ein Wesen, das andre beschützt.\nAus Knochen und Blut,\nmit Stift in die Seiten geritzt.\nDas Blut vom Schreiber,\nder Knochen vom Land,\nvermischt zur Vollendung\nund signiert mit der Hand.\"", sourceObjective = "Sammelt Knochen der Piraten von Zem'lan und vermahlt sie zu einem feinen Pulver. Vermischt das Pulver mit Eurem Blut, um eine Phiole mit Osseintinte zu erschaffen. Unterschreibt danach die Blutwachenchronik.", progress = "Man sollte bei all dem Blut, das man für die Prüfungen geben muss, meinen, man wäre am Ende bleich wie ein Gespenst.\n\nOder vielleicht einfach eine Woche lang im Koma.", completion = "Es scheint, als wärt Ihr angenommen worden.\n\n<Veriss deutet auf das Buch. Ihr blickt hinüber und seht ein Bild von Euch selbst neben der großen Bestie. Eure Signatur glänzt oben auf der Seite.>\n\nNun könnt Ihr den Vertrag der Blutwache nutzen.\n\nAchtet jedoch auf die Gesundheit des Wächters. Wenn sie zu sehr sinkt, könnte er sich an Euch nähren.", sourceObjectiveStatus = "unverified-source-field" }
quests[49879] = { id = 49879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tödliche Texte", description = "<Als Ihr das Buch öffnet, überkommt Euch ein plötzliches Frösteln. Ihr verdrängt das Gefühl, als Ihr den Vers lest.>\n\n\"Das Leben wird mit Blut riskiert,\nmit Glück das Gelöbnis wird akzeptiert.\nNutzt klare Linien und ruhigen Atem,\nder kleinste Verrutscher,\nund Ihr habt Euch verraten.\"\n\n<Als Ihr die Zauberformel zu Ende gelesen habt, erscheint ein Federkiel neben dem Buch.>", sourceObjective = "Nehmt den Federkiel und beginnt Eure Prüfung.", completion = "Gut gemacht, junger Blutschreiber.\n\nIhr könnt nun den Vertrag der Vergessenheit einsetzen. Damit beschwört Ihr ein Wesen, das... Nun ja, sagen wir einfach, wenn es beißt, bellt es nicht.\n\nEs schnappt sich gern Wesen, die dem Tode nahe sind. Und da macht es bei Euch keine Ausnahme, also seid vorsichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[49880] = { id = 49880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch Blut gebunden", description = "Wie mir scheint, seid Ihr hier fertig, {name}. Danke noch mal, dass Ihr mein Buch zurückgebracht habt. Ihr könnt Euch sicher vorstellen, wie es wirkt, wenn ein Meister so etwas verliert.\n\nAber nur zwischen uns beiden, das war noch der einfache Teil. Wartet nur, bis Ihr den Großmeister trefft.\n\nEure Ausbilderin wird Euch dazu weiter informieren. Viel Glück, {name}!", sourceObjective = "Kehrt zu Zooey Tintenritzel im Tiragardesund zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[49881] = { id = 49881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Vers", description = "Wie es scheint, seid Ihr hier fertig, {name}. Ich danke Euch nochmals, dass Ihr mein Buch zurückgebracht habt.\n\nAber nur zwischen uns beiden, das war noch der einfache Teil. Wartet nur, bis Ihr den Großmeister trefft.\n\nFalls es Euch entgangen sein sollte, man benötigt einen besonderen Federkiel, um diese Verträge einzusetzen. Und er ist derjenige, der Euch zeigt, wie man einen herstellt.\n\nEr heißt Miju und lebt auf einer Insel draußen vor der Südküste von Zuldazar. Viel Glück, {name}!", sourceObjective = "Sucht Miju im südlichen Zuldazar auf, um mit Eurer letzten Prüfung zu beginnen.", completion = "Was ist denn das? Noch ein Neuling, der die Kunst der Blutschriften erlernen möchte?\n\nNun gut, für welchen Vertrag soll der Federkiel denn sein?\n\n<Ihr erklärt Miju, dass Ihr alle vier Verträge erlernt habt und einen Federkiel für alle benötigt.>\n\nALLE VIER?! Meine Güte... Das gab es nicht mehr seit... Mal überlegen...\n\n<Miju führt leise Selbstgespräche.>\n\nIst wohl schon zu lange her. Aber ja, ich kenne das Rezept noch. Dann erwartet Euch eine Prüfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[49882] = { id = 49882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Federkielprüfung", description = "Das Objekt Eurer Begierde ist das Rezept für Lana'thels blutigen Federkiel, <junger Herr/junge Dame>. Ich...\n\n<Miju deutet auf einen Haufen Kram.>\n\nIch bin die einzige andere Person, die einen solchen hat... ähm... irgendwo. Doch seid gewarnt, diese Prüfung könnte Euch ins Verderben führen.\n\nIch werde alle vier Verträge gegen Euch wirken. Ihr müsst jede einzelne Kreatur bezwingen, um von jeder eine Rune zu erlernen, die in Euren Federkiel geschnitzt werden muss.\n\nWenn Ihr alle vier Runen erlernt habt, ist Eure Prüfung vollendet.", sourceObjective = "Sprecht mit Miju, um die letzte Prüfung zu beginnen und das Wissen zur Herstellung Eures Federkiels zu erlernen.", completion = "Gut gemacht, junger Schreiber. Wirklich gut gemacht!\n\nNun habt Ihr das Wissen. Es ist da drinnen.\n\n<Miju versucht, Euren Kopf anzutippen, doch Ihr tretet im rechten Moment einen Schritt zurück.>\n\nIhr seid schnell, vermutlich habt Ihr so die Prüfung überstanden. Nun überlasse ich Euch das letzte Wissen, das Ihr zur Fertigung eines Federkiels braucht.\n\nNun gut, lebt wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[49884] = { id = 49884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das blaue Licht der Hoffnung", description = "Wir müss'n nur noch eins erledig'n!\n\nDen zweit'n Turm noch, un' die Flotte gehört wieder uns!\n\nKommt an Bord, damit wir die Sache zu Ende bring'n könn'!", sourceObjective = "Fliegt mit Käpt'n Grez'ko und entzündet das Signalfeuer auf dem Turm.", completion = "Ihr habt die Flotte gerettet un' die Bucht der Könige beschützt!\n\nGut gemacht, {name}! Wir Kapitäne sind doch 'n schlauer Hauf'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49886] = { id = 49886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer der Nase nach", description = "Ihr da! Ich könnte Eure Hilfe brauchen!\n\nDieses Gebiet ist nicht sicher. Die Stacheleber haben unter uns ein Netzwerk aus Tunneln gegraben, über das sie einen jederzeit überfallen können, wenn man zu Fuß unterwegs und etwas unachtsam ist.\n\nZu unserem Glück hat Hubert hier einen richtig guten Riecher für Borstenrücken und kann sie selbst im Boden aufspüren. Merzt ein paar von diesen Ganoven aus, damit wir zu Fuß auf den Höfen wieder etwas sicherer sind.\n\nIn den nordöstlichen Feldern gibt es eine besonders große Ansammlung von ihnen. Gute Jagd!", sourceObjective = "Spürt mit Huberts Hilfe 5 panische Tunnelgräber auf und tötet sie.", completion = "Ha! Ich wette, der gute alte Hubert hat sie mächtig erschreckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[49887] = { id = 49887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwangsarbeit", description = "<Der Arbeiter ist durch Magie gebunden und kann nur mit großer Mühe sprechen.>\n\nH... Helft... uns...\n\n<Er hebt quälend langsam einen Finger und deutet auf den Anker in der Nähe.>\n\nBitte...", sourceObjective = "Befreit Samuel Willem.", progress = "<Er scheint keine Kraft mehr zu haben, noch weiter zu antworten.>", completion = "Zumindest haben sich nicht alle Gezeitenweisen gegen uns gewendet.\n\nNoch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[49888] = { id = 49888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Ein bisschen Mojo" }
quests[49890] = { id = 49890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drustfall", description = "Ich glaube, an diesem Höhleneingang da drüben sehe ich noch mehr Zeichnungen. Kommt, lasst uns nachsehen, was noch zu finden ist.", sourceObjective = "Untersucht die Eishöhle.", completion = "Die Zeichnungen könnten Propaganda der Drust gewesen sein, die besagt, dass er noch lebt, aber diese Stimme!\n<Morgenlichts Gesichtszüge verfinstern sich.>\nEs sieht so aus, als ob wir alle uns beim endgültigen Schicksal von Gorak Tul geirrt haben. Mir läuft es kalt den Rücken herunter, wenn ich daran denke, was sein nächster teuflischer Plan sein könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[49896] = { id = 49896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Falkenforst!", description = "Unser Aufenthalt hier hat sich gelohnt. Die Wachen in Aroms Wehr werden mit den wenigen verbliebenen Truppen der Drust fertig. Ich vermute allerdings, dass der Drustanführer und seine Magie hier noch eine größere Rolle spielen werden.\n\nDennoch müssen wir unsere Mission nach Falkenforst fortsetzen. Der Pfad auf der anderen Seite dieser Ruinen wird uns dorthinbringen.\n\nIch reite voraus und treffe Euch dann außerhalb der Stadt!", sourceObjective = "Trefft Euch mit Inquisitorin Morgenlicht außerhalb von Falkenforst.", completion = "Die Stadt wird belagert! Kein Wunder, dass wir nichts von hier gehört haben. Wir müssen ihnen helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49897] = { id = 49897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unerklärliche schaffen", description = "Wisst Ihr, was die Leute lieben? Das Unerklärliche! Das Problem ist nur, dass hier alles erklärbar ist. \n\nDaher habe ich mir einen Plan ausgedacht, wie wir unser eigenes Phä-gnom-en erschaffen können. Es gibt da diese Geschichten über seltsame Mischwesen: halb Schlange, halb Huhn. Es heißt, sie sollen ihre Opfer zu Stein erstarren lassen können. Tja, die Hühner habe ich schon, jetzt fehlen nur noch die Schlangen.\n\nDas ist aber kein großes Problem. Ihr müsst nur die Hühner fangen und diese robotischen Schwänze an ihnen festmachen.", sourceObjective = "Fangt 5 unscheinbare Hühner.", completion = "Fantastisch! Jetzt können wir die Rundfahrt durch unser Resort zur \"Safari der Mysterien\" machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[49898] = { id = 49898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klarer Sieg", description = "<Der geisterhafte Hauptmann kämpft weiter, während sie spricht, ganz in der Hitze des Gefechts gefangen. Ihr ist nicht bewusst, dass der Krieg seit Jahrhunderten vorbei ist.>\n\nWieso steht Ihr da nur herum? Wir haben sie bis auf ihre letzten Krieger und diese verfluchten Runenkonstrukte niedergerungen, aber der Krieg ist noch nicht vorbei!\n\nOberst Kronsteig braucht uns, damit wir die Linie halten! Tötet so viele der Drust wie möglich und der Krieg könnte vielleicht heute noch zu Ende gehen. Seht zu, dass Ihr Euch wieder in den Kampf stürzt!", sourceObjective = "Tötet 15 Drustskelette.", completion = "Nicht übel! Vielleicht machen wir doch noch einen brauchbaren Soldaten aus Euch!\n\nDafür werden sie Oberst Kronsteig zum Lord machen, da bin ich sicher. Man wird sich an Eure Tapferkeit erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[49901] = { id = 49901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Yazma, die gefallene Priesterin", description = "Zul weiß, dass wir nicht zulass'n dürf'n, dass der erste König sich aus sei'm Grab erhebt. Dazar wär mehr als nur 'n Strohmann für Zuls Trollimperium, er wär 'ne Macht, die es mit den Loa selbst aufnehm'n könnte.\n\nIch darf Zul nicht entkommen lass'n. Ich werde ihn mit mein' Leuten verfolg'n. Doch Ihr solltet mit Euern Leuten Atal'Dazar betret'n. Yazma wird versuch'n, Zeit zu gewinn' un' den Zugang zu den Gräbern zu versperr'n. Ihr müsst Euch bis zu ihr durchkämpf'n un' werdet dafür Verbündete brauch'n. Tötet Yazma.", sourceObjective = "Bezwingt Yazma in Atal'Dazar.", completion = "Yazmas abscheulicher Verrat lässt sich kaum in Worte fass'n.\n\nEs könnte uns 'n wenig Zeit kost'n, noch tiefer in Atal'Dazar vorzudringen. In der Zwischenzeit gibt's noch mehr zu tun.", sourceObjectiveStatus = "unverified-source-field" }
